'use client';

import { Component, useEffect, useMemo, useRef, useState } from 'react';
import { BookOpen, ClipboardCheck, Database, FileSpreadsheet, GraduationCap, Home, LogOut, Settings, Sparkles, Upload, Users } from 'lucide-react';
import { type CurriculumCourse } from '@/lib/default-curriculum';
import { parseOfficialWorkbook, splitIntegratedOfficialFile, type ParsedOfficialFile } from '@/lib/excel';
import { compareCourseSets } from '@/lib/domain.mjs';
import { compositeHeaders, detectHeaderRange, expandMergedCells, mapHeaderColumns, matrixCourseColumns, matrixCoursesFromRow, normalizeHeader } from '@/lib/reference-sheet.mjs';
import { parseEducationGuidePage, selectionLabel } from '@/lib/education-guide-pdf';
import { parseSchoolBookHwpx } from '@/lib/school-book-hwpx';
import * as XLSX from 'xlsx';
import * as pdfjsLib from 'pdfjs-dist/legacy/build/pdf.mjs';

type Role = 'student' | 'admin';
type Session = { token: string; role: Role; label: string };
type Notice = { type: 'error' | 'warn' | 'success'; text: string } | null;

const statusLabels: Record<string, string> = {
  draft: '작성 중', submitted: '제출 완료', resubmitted: '재제출 완료', revision_requested: '수정 요청', pending: '제출 완료', confirmed: '제출 완료', recheck_required: '제출 완료',
  open: '진행 중', closed: '마감', unreviewed: '미확인',
};
const statusTone = (status: string) => status === 'submitted' || status === 'resubmitted' || status === 'confirmed' || status === '변경 없음' || status === '일치' ? 'green' : status === 'pending' || status === '과목 추가' ? 'purple' : status === 'draft' ? 'gray' : status.includes('확인') || status.includes('없음') || status.includes('등장') ? 'amber' : 'red';
const api = async (path: string, token: string, init?: RequestInit): Promise<any> => {
  const response = await fetch(path, { ...init, headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}`, ...init?.headers } });
  const data: any = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || '처리 중 문제가 생겼습니다.');
  return data;
};
const semesterLabel = (grade: number, semester: number) => `${grade}학년 ${semester}학기`;
const Badge = ({ children, tone = 'purple' }: { children: React.ReactNode; tone?: string }) => <span className={`badge ${tone}`}>{children}</span>;
const NoticeBox = ({ notice }: { notice: Notice }) => notice ? <div className={`message ${notice.type}`} role="status">{notice.text}</div> : null;
const CourseTags = ({ courses }: { courses?: string[] }) => courses?.length ? <div className="course-tags">{courses.map((course, index) => <span className="course-tag" key={`${course}-${index}`}>{course}</span>)}</div> : <span className="panel-sub">없음</span>;
const verificationLabel = (status: string) => status === '실제 결과 없음' ? '공식 결과 없음' : status === '2차 자료에서 확인되지 않음' ? '공식 결과 없음' : ['과목 추가','과목 삭제','과목 변경'].includes(status) ? '변경 있음' : status;

export default function PlannerApp({ mode = 'student' }: { mode?: 'student' | 'teacher' }) {
  const [session, setSession] = useState<Session | null>(null);
  return <div className="app-shell">{session ? (session.role === 'student' ? <StudentApp session={session} onLogout={() => setSession(null)} /> : <AdminApp session={session} onLogout={() => setSession(null)} />) : <Login onLogin={setSession} lockedRole={mode === 'teacher' ? 'admin' : 'student'} />}<div className="footer-note">💖 Made by 꿈을 응원하는 현정T 💖</div></div>;
}

function Login({ onLogin, lockedRole }: { onLogin: (session: Session) => void; lockedRole: Role }) {
  const [role] = useState<Role>(lockedRole);
  const [form, setForm] = useState({ entranceYear: '2026', currentClass: '', currentNumber: '', name: '', password: '' });
  const [notice, setNotice] = useState<Notice>(null);
  const [loading, setLoading] = useState(false);
  const submit = async (event: React.FormEvent) => {
    event.preventDefault(); setLoading(true); setNotice(null);
    try {
      const body = role === 'admin' ? { role, password: form.password } : { role, entranceYear: Number(form.entranceYear), currentClass: Number(form.currentClass), currentNumber: Number(form.currentNumber), name: form.name };
      const result = await fetch('/api/auth', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
      const data: any = await result.json();
      if (!result.ok) throw new Error(data.error || '로그인하지 못했습니다.');
      onLogin({ token: data.token, role, label: role === 'admin' ? '선생님' : `${form.name} 학생` });
    } catch (error) { setNotice({ type: 'error', text: error instanceof Error ? error.message : '로그인하지 못했습니다.' }); }
    finally { setLoading(false); }
  };
  return <main className="login-wrap"><section className="surface login-card">
    <div className="status-chip"><Sparkles size={16} /> {role === 'student' ? '수강설계와 공식 결과를 함께 확인해요' : '학생 신청안과 공식 결과를 살펴봐요'}</div>
    <div className="brand-icon">{role === 'student' ? '🏫' : '👨‍🏫💖'}</div><h1 className="brand-title">{role === 'student' ? '배정고 수강설계 점검표' : '배정고 선생님 페이지'}</h1>
    <p className="brand-copy">{role === 'student' ? '내가 만든 신청안, 담임 확인 내용, 학교 공식 수강신청 결과를 한곳에서 확인하세요.' : '학생 신청안을 확인하고 학교 공식 결과를 안전하게 관리합니다.'}</p>
    <form onSubmit={submit}>
      {role === 'student' ? <div className="form-grid">
        <div className="field"><label htmlFor="entranceYear">입학년도</label><input id="entranceYear" className="control" inputMode="numeric" value={form.entranceYear} onChange={(e) => setForm({ ...form, entranceYear: e.target.value })} /></div>
        <div className="field"><label htmlFor="studentName">이름</label><input id="studentName" className="control" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></div>
        <div className="field"><label htmlFor="currentClass">현재 반</label><input id="currentClass" className="control" inputMode="numeric" value={form.currentClass} onChange={(e) => setForm({ ...form, currentClass: e.target.value })} /></div>
        <div className="field"><label htmlFor="currentNumber">현재 번호</label><input id="currentNumber" className="control" inputMode="numeric" value={form.currentNumber} onChange={(e) => setForm({ ...form, currentNumber: e.target.value })} /></div>
      </div> : <div className="field"><label htmlFor="adminPassword">선생님 비밀번호</label><input id="adminPassword" className="control" type="password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} /></div>}
      <NoticeBox notice={notice} /><button className="primary-btn full-btn" disabled={loading}>{loading ? '확인 중...' : role === 'student' ? '내 점검표 보기 ✨' : '선생님 화면 열기'}</button>
    </form>
    {role === 'student' ? <a className="teacher-link" href="/teacher.html">👨‍🏫 선생님 페이지</a> : <a className="teacher-link" href="/">← 학생 페이지로 돌아가기</a>}
  </section></main>;
}

const studentNav = [
  ['current', <Home key="i" size={18} />, '현재 최종 결과'], ['plan', <BookOpen key="i" size={18} />, '내가 작성한 신청안'], ['review', <ClipboardCheck key="i" size={18} />, '담임 확인 내용'], ['history', <Database key="i" size={18} />, '이전 차수 결과'], ['changes', <Sparkles key="i" size={18} />, '1차 → 2차 변경'],
] as const;

function StudentApp({ session, onLogout }: { session: Session; onLogout: () => void }) {
  const [view, setView] = useState('current');
  const [data, setData] = useState<any>(null);
  const [notice, setNotice] = useState<Notice>(null);
  const load = async () => { try { setData(await api('/api/overview', session.token)); } catch (e) { setNotice({ type: 'error', text: e instanceof Error ? e.message : '자료를 불러오지 못했습니다.' }); } };
  useEffect(() => { load(); }, []);
  const student = data?.student;
  return <div className="shell-wide">
    <header className="surface topbar"><div className="brand-small"><span>🏫</span><strong>배정고 수강설계 점검표</strong></div><div className="top-actions"><span className="user-label">{session.label}</span><button className="ghost-btn" onClick={onLogout}><LogOut size={16} /> 로그아웃</button></div></header>
    <div className="layout"><nav className="surface side-nav" aria-label="학생 메뉴">{studentNav.map(([key, icon, label]) => <button key={key} className={view === key ? 'active' : ''} onClick={() => setView(key)}>{icon}{label}</button>)}</nav>
      <main className="content"><section className="surface page-head"><span className="eyebrow">{student ? `${student.entrance_year}년 입학생 · ${student.current_class}반 ${student.current_number}번` : '학생 자료'}</span><h1>{student?.name || '학생'}님의 수강신청 점검표</h1><p>신청안과 공식 결과는 서로 다른 자료로 안전하게 보관됩니다.</p></section><NoticeBox notice={notice} />
        {!data ? <div className="surface empty">자료를 불러오는 중입니다.</div> : view === 'current' ? <CurrentResult data={data} /> : view === 'plan' ? <PlanEditor data={data} session={session} reload={load} /> : view === 'review' ? <ReviewView data={data} /> : view === 'history' ? <OfficialHistory data={data} /> : <StudentChanges data={data} />}
      </main></div>
  </div>;
}

function groupOfficial(rows: any[]) {
  const groups = new Map<string, { round: number; grade: number; semester: number; courses: string[] }>();
  for (const row of rows || []) { const key = `${row.round_number}-${row.target_grade}-${row.target_semester}`; const group = groups.get(key) || { round: row.round_number, grade: row.target_grade, semester: row.target_semester, courses: [] as string[] }; if (row.course_name) group.courses.push(row.course_name); groups.set(key, group); }
  return [...groups.values()].sort((a, b) => a.round - b.round || a.grade - b.grade || a.semester - b.semester);
}

function CurrentResult({ data }: { data: any }) {
  const groups = groupOfficial(data.official);
  const latestRound = Math.max(0, ...groups.map((g) => g.round));
  const latest = groups.filter((g) => g.round === latestRound);
  const planStatus = data.rounds?.sort((a: any, b: any) => b.round_number - a.round_number)[0]?.plan_status;
  return <>
    <div className="grid-cards"><div className="metric"><span>현재 기준</span><strong>{latestRound ? `${latestRound}차 공식 결과` : '업로드 전'}</strong></div><div className="metric"><span>담임 확인</span><strong style={{fontSize:'1.2rem'}}>{statusLabels[planStatus] || '신청안 없음'}</strong></div><div className="metric"><span>희망 대학·학과</span><strong>{data.preferences?.length || 0}개</strong></div><div className={`metric ${!latest.length ? 'alert' : ''}`}><span>확인할 내용</span><strong>{latest.length ? '0건' : '1건'}</strong></div></div>
    <section className="surface panel"><div className="panel-head"><div><h2>현재 최종 수강신청 결과</h2><p className="panel-sub">학교 공식 결과 중 가장 최신 차수를 보여줍니다. 학생은 이 내용을 수정할 수 없습니다.</p></div>{latestRound > 0 && <Badge tone="green">{latestRound}차 반영 완료</Badge>}</div>{latest.length ? <ResultGroups groups={latest} curriculum={data.curriculum} descriptions={data.courseDescriptions} requirements={data.requirements} /> : <div className="empty">아직 학교 공식 결과가 올라오지 않았습니다.<br />신청안은 ‘내가 작성한 신청안’에서 확인할 수 있어요.</div>}</section>
    <RecommendationSummary data={data} courses={latest.flatMap((g) => g.courses)} />
  </>;
}

function descriptionSourceLabel(description: any) {
  if (description.source_kind === 'official') return description.source_name || `${description.source_year || ''}학년도 공식 과목 안내 자료`;
  if (description.source_kind === 'merged') return description.source_name || '수동 설명과 공식 자료를 병합한 설명';
  return description.source_name || '선생님 직접 입력';
}

function CourseDescription({ name, info, recommendations, description }: { name: string; info: any; recommendations: string[]; description?: any }) {
  const badges = <>{info && <Badge tone="gray">{{general:'일반선택',career:'진로선택',convergence:'융합선택'}[info.selection_type as 'general']}</Badge>} {recommendations.includes('core') && <Badge tone="pink">핵심과목</Badge>} {!recommendations.includes('core') && recommendations.includes('recommended') && <Badge tone="purple">권장과목</Badge>}</>;
  if (!description) return <span className="course-chip">{name} {badges}</span>;
  return <details className="course-chip course-description"><summary>{name} {badges}<span className="course-help">설명 보기</span></summary><div className="course-description-body">{description.overview && <p><strong>과목 개요</strong>{description.overview}</p>}{description.learning_content && <p><strong>주요 학습 내용</strong>{description.learning_content}</p>}{description.course_nature && <p><strong>과목 성격</strong>{description.course_nature}</p>}{description.note && <p><strong>관련 과목 및 위계·이수 정보</strong>{description.note}</p>}{description.related_careers && <p><strong>관련 진로·학과</strong>{description.related_careers}</p>}<p className="course-source">출처: {descriptionSourceLabel(description)}</p></div></details>;
}

function ResultGroups({ groups, curriculum, descriptions, requirements }: { groups: any[]; curriculum: any[]; descriptions: any[]; requirements: any[] }) {
  const courseInfo = new Map((curriculum || []).map((c: any) => [c.course_name, c]));
  const descriptionMap = new Map((descriptions || []).map((d: any) => [d.course_name, d]));
  const reqMap = new Map<string, string[]>();
  for (const r of requirements || []) { const items = reqMap.get(r.course_name) || []; items.push(r.recommendation_type); reqMap.set(r.course_name, items); }
  return <div className="result-block">{groups.map((g) => <div className="semester-result" key={`${g.round}-${g.grade}-${g.semester}`}><h3>{semesterLabel(g.grade, g.semester)}</h3><div className="chips">{g.courses.map((name: string) => <CourseDescription key={name} name={name} info={courseInfo.get(name)} recommendations={reqMap.get(name) || []} description={descriptionMap.get(name)} />)}</div></div>)}</div>;
}

function RecommendationSummary({ data, courses }: { data: any; courses: string[] }) {
  const selected = new Set(courses);
  const missing = (data.requirements || []).filter((r: any) => !selected.has(r.course_name));
  const offered = new Set((data.curriculum || []).map((item:any) => item.course_name)); const unavailable=[...new Set((data.requirements||[]).filter((item:any)=>!offered.has(item.course_name)).map((item:any)=>item.course_name))];
  return <section className="surface panel"><div className="panel-head"><div><h2>희망 대학·학과 기준 확인</h2><p className="panel-sub">대학 자료는 참고용입니다. 최종 선택은 담임교사와 확인하세요.</p></div></div>{!data.preferences?.length ? <div className="empty">희망 대학과 학과를 신청안 화면에서 먼저 입력해주세요.</div> : !data.requirements?.length ? <div className="message warn">자료 없음 / 담임 확인 필요</div> : <>{missing.length ? <div className="message warn">선택하지 않은 핵심·권장과목이 {missing.length}개 있습니다: {[...new Set(missing.map((r: any) => r.course_name))].join(', ')}</div> : <div className="message success">등록된 핵심·권장과목이 현재 결과에 모두 포함되어 있습니다.</div>}{unavailable.length>0&&<div className="message warn">추천자료에는 있으나 학교 선택과목 자료에서 확인되지 않음: {unavailable.join(', ')}</div>}</>}</section>;
}

function PlanEditor({ data, session, reload }: { data: any; session: Session; reload: () => Promise<void> }) {
  const openRound = data.rounds?.find((r: any) => r.status === 'open') || data.rounds?.[data.rounds.length - 1];
  const planRows = (data.plans || []).filter((p: any) => p.round_id === openRound?.id);
  const existingPlan = planRows[0];
  const initialCourses = planRows.filter((p: any) => p.course_name).map((p: any) => ({ targetGrade: p.target_grade, targetSemester: p.target_semester, courseName: p.course_name }));
  // 학생에게는 선생님이 해당 입학년도 교육과정에 실제 개설로 등록한 과목만 보여줍니다.
  // 예시 교육과정은 선생님 설정 화면의 초기 등록 보조용으로만 남겨 둡니다.
  const curriculum: CurriculumCourse[] = (data.curriculum || []).map((c: any) => ({ targetGrade: c.target_grade, targetSemester: c.target_semester, area: c.area, courseName: c.course_name, selectionType: c.selection_type }));
  const [semester, setSemester] = useState('2-1');
  const [selected, setSelected] = useState<Array<{ targetGrade: number; targetSemester: number; courseName: string }>>(initialCourses);
  const [careerGoal, setCareerGoal] = useState(data.profile?.career_goal || '');
  const [academicTrack, setAcademicTrack] = useState(data.profile?.academic_track || 'undecided');
  const [memo, setMemo] = useState(data.profile?.counseling_memo || '');
  const [preferences, setPreferences] = useState(Array.from({ length: 3 }, (_, i) => data.preferences?.[i] ? { university: data.preferences[i].university, department: data.preferences[i].department, admissionsYear: data.preferences[i].admissions_year } : { university: '', department: '', admissionsYear: 2028 }));
  const [notice, setNotice] = useState<Notice>(null);
  const [saving, setSaving] = useState(false);
  const [, setPlanId] = useState(existingPlan?.plan_id || '');
  const touched = useRef(false); const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const currentStatus = existingPlan?.status || 'draft';
  const locked = ['submitted','resubmitted','pending','confirmed','recheck_required'].includes(currentStatus) || !openRound || openRound.status !== 'open';
  const requirementMap = useMemo(() => { const map = new Map<string, any[]>(); for (const r of data.requirements || []) map.set(r.course_name, [...(map.get(r.course_name) || []), r]); return map; }, [data.requirements]);
  const saveDraft = async (quiet = false) => {
    if (!openRound || locked) return ''; setSaving(true);
    try { const result = await api('/api/action', session.token, { method: 'POST', body: JSON.stringify({ action: 'savePlan', roundId: openRound.id, courses: selected, studentMemo: memo }) }); setPlanId(result.planId); if (!quiet) setNotice({ type: 'success', text: '신청안을 임시 저장했습니다.' }); return result.planId as string; }
    catch (e) { setNotice({ type: 'error', text: e instanceof Error ? e.message : '저장하지 못했습니다.' }); }
    finally { setSaving(false); }
    return '';
  };
  useEffect(() => { if (!touched.current || locked) return; if (timer.current) clearTimeout(timer.current); timer.current = setTimeout(() => saveDraft(true), 900); return () => { if (timer.current) clearTimeout(timer.current); }; }, [selected, memo]);
  const toggle = (course: CurriculumCourse) => { if (locked) return; touched.current = true; setSelected((items) => items.some((x) => x.targetGrade === course.targetGrade && x.targetSemester === course.targetSemester && x.courseName === course.courseName) ? items.filter((x) => !(x.targetGrade === course.targetGrade && x.targetSemester === course.targetSemester && x.courseName === course.courseName)) : [...items, { targetGrade: course.targetGrade, targetSemester: course.targetSemester, courseName: course.courseName }]); };
  const saveProfile = async (quiet = false) => {
    if (locked) return false;
    try {
      const result = await api('/api/action', session.token, { method: 'POST', body: JSON.stringify({ action: 'saveProfile', careerGoal, academicTrack, counselingMemo: memo, preferences }) });
      if (!quiet) setNotice({ type: result.statusChanged ? 'warn' : 'success', text: result.statusChanged ? '진로 정보가 바뀌어 신청안이 재확인 필요 상태가 되었습니다.' : '진로와 희망 대학·학과를 저장했습니다.' });
      return true;
    } catch (e) { setNotice({ type: 'error', text: e instanceof Error ? e.message : '저장하지 못했습니다.' }); return false; }
  };
  const saveAll = async () => { const profileSaved = await saveProfile(true); if (!profileSaved) return; await saveDraft(false); await reload(); };
  const submit = async () => { const profileSaved = await saveProfile(true); if (!profileSaved) return; const savedPlanId = await saveDraft(true); if (!savedPlanId) return; try { await api('/api/action', session.token, { method: 'POST', body: JSON.stringify({ action: 'submitPlan', planId: savedPlanId, snapshot: { selected, careerGoal, academicTrack, preferences } }) }); setNotice({ type: 'success', text: currentStatus === 'revision_requested' ? '수정한 신청안을 다시 제출했습니다.' : '신청안이 제출되었습니다. 담임이 수정이 필요한 경우 안내합니다.' }); await reload(); } catch (e) { setNotice({ type: 'error', text: e instanceof Error ? e.message : '제출하지 못했습니다.' }); } };
  const [grade, term] = semester.split('-').map(Number); const visible = curriculum.filter((c) => c.targetGrade === grade && c.targetSemester === term); const areas = [...new Set(visible.map((c) => c.area))];
  const selectedCourses = selected.map((course) => course.courseName);
  const schoolBookByCourse = new Map((data.schoolBookEntries || []).map((row:any) => [row.subject_name, row]));
  return <>
    <section className="surface panel"><div className="panel-head"><div><h2>내 기본정보</h2><p className="panel-sub">신청안은 학교 공식 수강신청 결과와 별도로 저장됩니다.</p></div><Badge tone={statusTone(currentStatus)}>{statusLabels[currentStatus] || '작성 중'}</Badge></div>
      <div className="student-info-grid"><div><span>입학년도</span><strong>{data.student?.entrance_year}년</strong></div><div><span>반 · 번호</span><strong>{data.student?.current_class}반 {data.student?.current_number}번</strong></div><div><span>이름</span><strong>{data.student?.name}</strong></div><div><span>현재 수강신청 차수</span><strong>{openRound ? `${openRound.round_number}차` : '준비 중'}</strong></div><div><span>현재 상태</span><strong>{statusLabels[currentStatus] || '작성 중'}</strong></div></div>
    </section>
    <section className="surface panel"><div className="panel-head"><div><h2>진로와 희망 대학·학과</h2><p className="panel-sub">관심 진로와 1순위만 입력해도 저장하고 담임 확인을 요청할 수 있어요.</p></div></div>
      <div className="form-grid"><div className="field"><label>관심 진로</label><input className="control" disabled={locked} value={careerGoal} onChange={(e) => { touched.current = true; setCareerGoal(e.target.value); }} placeholder="예: 생명과학 연구원" /></div><div className="field"><label>선택 계열</label><select className="control" disabled={locked} value={academicTrack} onChange={(e)=>{touched.current=true;setAcademicTrack(e.target.value);}}><option value="humanities">인문계열</option><option value="science">자연계열</option><option value="undecided">아직 미정</option></select></div></div>
      <div className="form-grid" style={{marginTop:12}}>{preferences.map((p, i) => <div className="field full" key={i}><label>{i === 0 ? '1순위 희망 대학·학과' : `${i + 1}순위 희망 대학·학과 (선택)`}</label><div className="split"><input className="control" disabled={locked} value={p.university} onChange={(e) => { touched.current = true; setPreferences(preferences.map((x, n) => n === i ? {...x, university:e.target.value}:x)); }} placeholder="희망 대학" /><input className="control" disabled={locked} value={p.department} onChange={(e) => { touched.current = true; setPreferences(preferences.map((x, n) => n === i ? {...x, department:e.target.value}:x)); }} placeholder="희망 학과 또는 모집단위" /></div></div>)}</div>
      <div className="field" style={{marginTop:12}}><label>학생 메모·상담 참고사항 (선택)</label><textarea className="control" disabled={locked} value={memo} onChange={(e) => { touched.current = true; setMemo(e.target.value); }} /></div>
      {locked && <div className="message warn">{['submitted','resubmitted','pending','confirmed','recheck_required'].includes(currentStatus) ? '신청안이 제출되었습니다. 담임교사가 확인 후 수정이 필요한 경우 안내합니다.' : '신청 기간이 마감되어 지금은 신청안을 수정할 수 없습니다.'}</div>}
    </section>
    <section className="surface panel"><div className="panel-head"><div><h2>{openRound ? `${openRound.round_number}차 학생 신청안` : '학생 신청안'}</h2><p className="panel-sub">과목은 교과 영역별로 확인할 수 있습니다. 핵심·권장과목 미선택은 제출을 막지 않고 알려드립니다.</p></div>{saving && <Badge tone="purple">자동 저장 중</Badge>}</div>
      {!openRound ? <div className="empty">선생님이 아직 신청 차수를 열지 않았습니다.</div> : <><div className="semester-tabs">{['2-1','2-2','3-1','3-2'].map((s) => <button key={s} className={semester === s ? 'active' : ''} onClick={() => setSemester(s)}>{s.replace('-', '학년 ')}학기</button>)}</div>
      {!visible.length ? <div className="empty">이 학기에 실제로 선택 가능한 과목이 아직 등록되지 않았습니다.<br />선생님께 교육과정 등록 여부를 확인해주세요.</div> : <div className="course-groups" style={{marginTop:14}}>{areas.map((area) => <details className="course-group" key={area} open><summary>{area} 영역 <span>{visible.filter((c) => c.area === area).length}과목</span></summary><div className="course-list">{visible.filter((c) => c.area === area).map((course) => { const checked = selected.some((x) => x.targetGrade === grade && x.targetSemester === term && x.courseName === course.courseName); const reqs = requirementMap.get(course.courseName) || []; const book=schoolBookByCourse.get(course.courseName); const coreCount = new Set(reqs.filter((r) => r.recommendation_type === 'core').map((r) => r.university)).size; const recommendedCount = new Set(reqs.filter((r) => r.recommendation_type === 'recommended').map((r) => r.university)).size; return <label className="course-row" key={course.courseName} title={reqs.map((r) => `${r.university} ${r.department} - ${r.recommendation_type === 'core' ? '핵심과목' : '권장과목'}`).join('\n')}><input type="checkbox" checked={checked} disabled={locked} onChange={() => toggle(course)} /><span className="course-main"><span className="course-name">{course.courseName}</span><span className="course-meta"><Badge tone="gray">{{general:'일반선택',career:'진로선택',convergence:'융합선택'}[course.selectionType]}</Badge>{book?.csat_priority&&<Badge tone="pink">수능 준비 우선</Badge>}{academicTrack==='humanities'&&book?.humanities_priority&&<Badge tone="purple">인문 우선</Badge>}{academicTrack==='science'&&book?.science_priority&&<Badge tone="purple">자연 우선</Badge>}{coreCount > 0 && <Badge tone="pink">핵심과목{coreCount > 1 ? ` · ${coreCount}개 대학` : ''}</Badge>}{!coreCount && recommendedCount > 0 && <Badge tone="purple">권장과목{recommendedCount > 1 ? ` · ${recommendedCount}개 대학` : ''}</Badge>}</span></span></label>; })}</div></details>)}</div>}</>}
    </section>
    <TrackCourseGuide data={data} academicTrack={academicTrack} selectedCourses={selectedCourses} />
    <PlanRecommendationAnalysis requirements={data.requirements || []} selectedCourses={selectedCourses} preferences={preferences} availableCourses={(data.curriculum || []).map((item:any)=>item.course_name)} />
    <section className="surface panel plan-actions"><div><h2>신청안 저장·제출</h2><p className="panel-sub">추천 과목을 선택하지 않아도 제출할 수 있습니다. 수정 요청이 있을 때만 다시 열어 수정합니다.</p></div><NoticeBox notice={notice} /><div className="toolbar"><button className="secondary-btn" disabled={locked || saving} onClick={saveAll}>임시 저장</button><button className="primary-btn" disabled={locked || saving} onClick={submit}>{currentStatus==='revision_requested'?'수정 후 다시 제출':'신청안 제출'}</button></div></section>
  </>;
}

function PlanRecommendationAnalysis({ requirements, selectedCourses, preferences, availableCourses }: { requirements: any[]; selectedCourses: string[]; preferences: any[]; availableCourses: string[] }) {
  const selected = new Set(selectedCourses);
  const core = requirements.filter((item) => item.recommendation_type === 'core');
  const recommended = requirements.filter((item) => item.recommendation_type === 'recommended');
  const unique = (items: any[]) => [...new Set(items.map((item) => item.course_name))];
  const selectedRecommended = unique(requirements.filter((item) => selected.has(item.course_name)));
  const missing = unique(requirements.filter((item) => !selected.has(item.course_name)));
  const unavailable=unique(requirements.filter((item)=>!new Set(availableCourses).has(item.course_name)));
  return <section className="surface panel"><div className="panel-head"><div><h2>대학·학과 추천과목 분석</h2><p className="panel-sub">등록된 기준자료를 참고로 비교합니다. 과목 선택을 강제하지 않습니다.</p></div></div>
    {!preferences.some((item) => item.university || item.department) ? <div className="empty">희망 대학 또는 희망 학과를 입력하면 추천과목을 비교해드려요.</div> : !requirements.length ? <div className="message warn">자료 없음 / 담임 확인 필요</div> : <><div className="recommendation-grid"><RecommendationBox title="핵심과목" tone="pink" courses={unique(core)} /><RecommendationBox title="권장과목" tone="purple" courses={unique(recommended)} /><RecommendationBox title="현재 선택한 추천과목" tone="green" courses={selectedRecommended} /><RecommendationBox title="현재 선택하지 않은 과목" tone="amber" courses={missing} /></div>{unavailable.length>0&&<div className="message warn" style={{marginTop:10}}>추천자료에는 있으나 학교 개설 여부 확인 필요: {unavailable.join(', ')}</div>}</>}
    {!!missing.length && <div className="message warn">희망 대학/학과 자료 기준으로 확인이 필요한 과목이 있습니다. 담임교사와 함께 확인해보세요.</div>}
  </section>;
}

function RecommendationBox({ title, tone, courses }: { title: string; tone: string; courses: string[] }) {
  return <div className={`recommendation-box ${tone}`}><div><Badge tone={tone}>{title}</Badge><strong>{courses.length}과목</strong></div><p>{courses.length ? courses.join(', ') : '해당 과목이 없습니다.'}</p></div>;
}

const trackLabels:any={humanities:'인문계열',science:'자연계열',undecided:'아직 미정',common:'공통'};
const priorityLabels:any={required:'필수','1':'1순위','2':'2순위','3':'3순위'};
function TrackCourseGuide({data,academicTrack,selectedCourses}:{data:any;academicTrack:string;selectedCourses:string[]}) {
  const selected=new Set(selectedCourses); const guideRows=(data.trackCourseGuides||[]).filter((row:any)=>academicTrack==='undecided'?row.academic_track==='common':row.academic_track===academicTrack||row.academic_track==='common');
  const bookRows=(data.schoolBookEntries||[]).filter((row:any)=>row.school_requirement==='required'||row.csat_priority||(academicTrack==='humanities'&&row.humanities_priority)||(academicTrack==='science'&&row.science_priority));
  const requirementMap=new Map<string,string[]>(); for(const row of data.requirements||[])requirementMap.set(row.course_name,[...(requirementMap.get(row.course_name)||[]),row.recommendation_type]);
  const descriptions=new Map((data.courseDescriptions||[]).map((row:any)=>[row.course_name,row])); const curriculum=new Map((data.curriculum||[]).map((row:any)=>[row.course_name,row]));
  const groups=['required','1','2','3'].map(priority=>({priority,rows:guideRows.filter((row:any)=>row.priority===priority)})); const missingRequired=groups[0].rows.filter((row:any)=>!selected.has(row.course_name)); const missingPriority=groups.slice(1).flatMap(group=>group.rows).filter((row:any)=>!selected.has(row.course_name));
  const courseCard=(row:any)=><div className="course-chip" key={row.id}><strong>{row.course_name}</strong> <Badge tone={row.priority==='required'?'red':row.priority==='1'?'pink':row.priority==='2'?'purple':'gray'}>{priorityLabels[row.priority]}</Badge>{selected.has(row.course_name)?<Badge tone="green">현재 선택함</Badge>:<Badge tone="amber">미선택</Badge>}{(requirementMap.get(row.course_name)||[]).includes('core')&&<Badge tone="pink">대학 핵심</Badge>}{!(requirementMap.get(row.course_name)||[]).includes('core')&&(requirementMap.get(row.course_name)||[]).includes('recommended')&&<Badge tone="purple">대학 권장</Badge>}{descriptions.get(row.course_name)&&<CourseDescription name={row.course_name} info={curriculum.get(row.course_name)} recommendations={requirementMap.get(row.course_name)||[]} description={descriptions.get(row.course_name)}/>}</div>;
  const missingSchoolRequired=bookRows.filter((row:any)=>row.school_requirement==='required'&&!selected.has(row.subject_name));
  const missingCsat=bookRows.filter((row:any)=>row.csat_priority&&!selected.has(row.subject_name));
  return <section className="surface panel"><div className="panel-head"><div><h2>계열별 과목 선택 가이드</h2><p className="panel-sub">학교 책자 기준·계열 기준·대학 추천은 서로 덮어쓰지 않고 함께 보여드립니다.</p></div><Badge tone="purple">{trackLabels[academicTrack]||'아직 미정'}</Badge></div>{academicTrack==='undecided'&&<div className="message">계열이 아직 미정이면 학교 공통 기준과 희망 대학·학과 자료만 우선 보여드립니다.</div>}{bookRows.length>0&&<div className="semester-result"><h3>학교 수강신청 안내 기준</h3><div className="chips">{bookRows.map((row:any)=><div className="course-chip" key={row.id}><strong>{row.subject_name}</strong>{row.school_requirement==='required'&&<Badge tone="red">학교 필수</Badge>}{row.csat_priority&&<Badge tone="pink">수능 준비 우선</Badge>}{academicTrack==='humanities'&&row.humanities_priority&&<Badge tone="purple">인문 우선</Badge>}{academicTrack==='science'&&row.science_priority&&<Badge tone="purple">자연 우선</Badge>}{selected.has(row.subject_name)?<Badge tone="green">현재 선택함</Badge>:<Badge tone="amber">미선택</Badge>}{descriptions.get(row.subject_name)&&<CourseDescription name={row.subject_name} info={curriculum.get(row.subject_name)} recommendations={requirementMap.get(row.subject_name)||[]} description={descriptions.get(row.subject_name)}/>}</div>)}</div></div>}{!guideRows.length?<div className="empty">이 계열의 별도 학교 우선순위 기준은 아직 등록되지 않았습니다. 학교 책자 및 희망 대학·학과 기준은 계속 확인할 수 있습니다.</div>:<>{groups.map(group=>group.rows.length?<div className="semester-result" key={group.priority}><h3>{group.priority==='required'?'학교 필수 이수':`${priorityLabels[group.priority]} 선택과목`}</h3><div className="chips">{group.rows.map(courseCard)}</div></div>:null)}{missingRequired.length>0&&<div className="message error">학교 필수 과목 중 선택하지 않은 과목이 있습니다: {missingRequired.map((row:any)=>row.course_name).join(', ')}</div>}{missingPriority.length>0&&<div className="message warn">{trackLabels[academicTrack]} 우선순위 과목 중 선택하지 않은 과목이 있습니다. 제출은 가능하며 담임과 함께 확인해보세요.</div>}</>}{missingSchoolRequired.length>0&&<div className="message error">학교 운영 기준상 필수로 안내된 과목을 선택하지 않았습니다: {missingSchoolRequired.map((row:any)=>row.subject_name).join(', ')}</div>}{missingCsat.length>0&&<div className="message warn">학교 진학지도 기준상 수능 준비를 위해 우선적으로 안내되는 과목을 선택하지 않았습니다. 제출은 가능하며 담임과 함께 확인해보세요.</div>}</section>;
}

function ReviewView({ data }: { data: any }) { return <section className="surface panel"><div className="panel-head"><div><h2>담임 검토 내용</h2><p className="panel-sub">신청안은 제출 후 잠기며, 담임이 수정 요청한 기록과 재제출 기록을 확인할 수 있습니다.</p></div></div>{data.reviews?.length ? <div className="result-block">{data.reviews.map((r: any) => <div className="semester-result" key={r.id}><div className="panel-head"><strong>{({submitted:'제출 완료',resubmitted:'재제출 완료',revision_requested:'수정 요청',pending:'제출 완료',confirmed:'제출 완료'} as any)[r.action] || r.action}</strong><span className="panel-sub">{new Date(r.created_at).toLocaleString('ko-KR')}</span></div>{r.comment && <p>{r.comment}</p>}</div>)}</div> : <div className="empty">아직 제출 또는 수정 요청 기록이 없습니다.</div>}</section>; }
function OfficialHistory({ data }: { data: any }) { const groups = groupOfficial(data.official); const rounds = [...new Set(groups.map((g) => g.round))]; return <section className="surface panel"><div className="panel-head"><div><h2>이전 차수 공식 결과</h2><p className="panel-sub">업로드된 결과는 차수별로 따로 보존됩니다.</p></div></div>{rounds.length ? rounds.map((round) => <div key={round} style={{marginBottom:18}}><h3>{round}차 공식 최종 결과</h3><ResultGroups groups={groups.filter((g) => g.round === round)} curriculum={data.curriculum} descriptions={data.courseDescriptions} requirements={data.requirements} /></div>) : <div className="empty">공식 결과가 아직 없습니다.</div>}</section>; }
function StudentChanges({ data }: { data: any }) { const groups = groupOfficial(data.official); const scopes = [...new Set(groups.map((g) => `${g.grade}-${g.semester}`))]; return <section className="surface panel"><div className="panel-head"><div><h2>1차 → 2차 변경 내역</h2><p className="panel-sub">과목 순서가 아니라 과목 목록 자체를 비교합니다.</p></div></div>{scopes.length ? scopes.map((scope) => { const [grade, semester] = scope.split('-').map(Number); const first = groups.find((g) => g.round === 1 && g.grade === grade && g.semester === semester); const second = groups.find((g) => g.round === 2 && g.grade === grade && g.semester === semester); if (!first || !second) return <div className="semester-result" key={scope}><h3>{semesterLabel(grade,semester)}</h3><Badge tone="amber">{first ? '2차 자료에서 확인되지 않음' : '2차 자료에 새로 등장'}</Badge></div>; const diff = compareCourseSets(first.courses, second.courses); return <div className="semester-result" key={scope}><div className="panel-head"><h3>{semesterLabel(grade,semester)}</h3><Badge tone={statusTone(diff.status)}>{diff.status}</Badge></div>{diff.changed ? <div className="diff-grid"><div className="diff-box remove"><strong>삭제</strong><div>{diff.removed.join(', ') || '없음'}</div></div><div className="diff-box add"><strong>추가</strong><div>{diff.added.join(', ') || '없음'}</div></div></div> : <div className="message success">신청 과목이 그대로 유지되었습니다.</div>}</div>; }) : <div className="empty">비교할 공식 결과가 없습니다.</div>}</section>; }

const adminNav = [
  ['dashboard', <Home key="i" size={18}/>, '대시보드'], ['students', <Users key="i" size={18}/>, '학생 확인'], ['upload', <Upload key="i" size={18}/>, '실제 결과 업로드'], ['verify', <ClipboardCheck key="i" size={18}/>, '결과 검증'], ['reference', <GraduationCap key="i" size={18}/>, '기준자료 관리'], ['settings', <Settings key="i" size={18}/>, '설정'],
] as const;

function AdminApp({ session, onLogout }: { session: Session; onLogout: () => void }) {
  const [view, setView] = useState('dashboard'); const [year, setYear] = useState(new Date().getFullYear()); const [data, setData] = useState<any>(null); const [notice, setNotice] = useState<Notice>(null);
  const load = async () => { try { setData(await api(`/api/overview?entranceYear=${year}`, session.token)); } catch (e) { setNotice({ type:'error', text:e instanceof Error ? e.message : '자료를 불러오지 못했습니다.' }); } };
  useEffect(() => { load(); }, [year]);
  return <div className="shell-wide"><header className="surface topbar"><div className="brand-small"><span>👨‍🏫💖</span><strong>배정고 선생님 페이지</strong></div><div className="top-actions"><label className="user-label" htmlFor="admin-year">입학년도</label><input id="admin-year" className="control" style={{width:96,minHeight:40}} inputMode="numeric" value={year} onChange={(e) => setYear(Number(e.target.value))}/><button className="ghost-btn" onClick={onLogout}><LogOut size={16}/> 로그아웃</button></div></header>
  <div className="layout"><nav className="surface side-nav" aria-label="선생님 메뉴">{adminNav.map(([key,icon,label]) => <button key={key} className={view===key?'active':''} onClick={() => setView(key)}>{icon}{label}</button>)}</nav><main className="content"><section className="surface page-head"><span className="eyebrow">{year}년 입학생</span><h1>{adminNav.find(([key])=>key===view)?.[2]}</h1><p>문제가 있는 학생과 확인할 자료가 먼저 보이도록 정리했습니다.</p></section><NoticeBox notice={notice}/>{!data ? <div className="surface empty">자료를 불러오는 중입니다.</div> : view==='dashboard'?<AdminDashboard data={data}/>:view==='students'?<AdminStudents data={data} session={session} reload={load}/>:view==='upload'?<UploadView year={year} session={session} reload={load}/>:view==='verify'?<VerificationView data={data} session={session} reload={load}/>:view==='reference'?<ReferenceView year={year} data={data} session={session} reload={load}/>:<SettingsView year={year} data={data} session={session} reload={load} onLogout={onLogout}/>}</main></div></div>;
}

function AdminDashboard({data}:{data:any}) { const counts = (data.plans||[]).reduce((a:any,p:any)=>(a[p.status]=(a[p.status]||0)+1,a),{}); const officialMismatch=(data.validations||[]).filter((item:any)=>item.validationStatus==='불일치').length; const recommendationAttention=(data.plans||[]).filter((plan:any)=>{const chosen=new Set((data.planCourses||[]).filter((course:any)=>course.plan_id===plan.id).map((course:any)=>course.course_name));return (data.planRequirements||[]).some((row:any)=>row.student_id===plan.student_id&&!chosen.has(row.course_name));}).length; return <><div className="grid-cards"><div className="metric"><span>전체 학생</span><strong>{data.students.length}</strong></div><div className="metric"><span>미제출</span><strong>{counts.draft||0}</strong></div><div className="metric"><span>제출 완료</span><strong>{(counts.submitted||0)+(counts.pending||0)+(counts.confirmed||0)+(counts.recheck_required||0)}</strong></div><div className="metric alert"><span>수정 요청</span><strong>{counts.revision_requested||0}</strong></div><div className="metric"><span>재제출 완료</span><strong>{counts.resubmitted||0}</strong></div></div><section className="surface panel"><div className="panel-head"><div><h2>먼저 확인할 학생</h2><p className="panel-sub">추천과목 경고는 자동 오류가 아닌 담임 상담 참고 정보입니다.</p></div></div><div className="chips"><Badge tone="amber">추천과목 확인 필요 {recommendationAttention}</Badge><Badge tone="red">공식 결과 불일치 {officialMismatch}</Badge><Badge tone="pink">수정 요청 {counts.revision_requested||0}</Badge></div></section></>; }

function AdminStudents({data,session,reload}:{data:any;session:Session;reload:()=>Promise<void>}) {
 const [query,setQuery]=useState(''); const [status,setStatus]=useState(''); const [round,setRound]=useState(''); const [classNo,setClassNo]=useState(''); const [attentionOnly,setAttentionOnly]=useState(false); const [selectedId,setSelectedId]=useState(''); const [comment,setComment]=useState(''); const [notice,setNotice]=useState<Notice>(null);
 const needsAttention=(p:any)=>{const selectedCourses=new Set((data.planCourses||[]).filter((c:any)=>c.plan_id===p.id).map((c:any)=>c.course_name));const hasMissingRecommendation=(data.planRequirements||[]).some((r:any)=>r.student_id===p.student_id&&!selectedCourses.has(r.course_name));const hasMissingRequired=(data.trackCourseGuides||[]).some((g:any)=>g.priority==='required'&&(p.academic_track==='undecided'?g.academic_track==='common':g.academic_track==='common'||g.academic_track===p.academic_track)&&!selectedCourses.has(g.course_name));const hasPreference=(data.planPreferences||[]).some((pref:any)=>pref.student_id===p.student_id&&pref.university&&pref.department);return p.status==='revision_requested'||p.status==='resubmitted'||hasMissingRecommendation||hasMissingRequired||!hasPreference;};
 const plans=(data.plans||[]).filter((p:any)=>(!query||`${p.name} ${p.current_number} ${p.current_class}`.includes(query))&&(!status||p.status===status)&&(!round||String(p.round_number)===round)&&(!classNo||String(p.current_class)===classNo)&&(!attentionOnly||needsAttention(p))).sort((a:any,b:any)=>Number(needsAttention(b))-Number(needsAttention(a))||a.current_class-b.current_class||a.current_number-b.current_number||a.name.localeCompare(b.name,'ko'));
 const selected=plans.find((p:any)=>p.id===selectedId)||(data.plans||[]).find((p:any)=>p.id===selectedId);
 const counts=(data.plans||[]).reduce((all:any,p:any)=>(all[p.status]=(all[p.status]||0)+1,all),{});
 const review=async()=>{if(!selected)return;if(!comment.trim()){setNotice({type:'error',text:'학생에게 전달할 수정 사유를 입력해주세요.'});return;}try{await api('/api/action',session.token,{method:'POST',body:JSON.stringify({action:'reviewPlan',planId:selected.id,decision:'revision_requested',comment})});setComment('');setNotice({type:'success',text:'수정 요청과 코멘트를 저장했습니다. 학생 신청안의 잠금이 해제됩니다.'});await reload();}catch(e){setNotice({type:'error',text:e instanceof Error?e.message:'처리하지 못했습니다.'});}};
 const courses=(data.planCourses||[]).filter((c:any)=>c.plan_id===selected?.id); const prefs=(data.planPreferences||[]).filter((p:any)=>p.student_id===selected?.student_id); const reqs=(data.planRequirements||[]).filter((r:any)=>r.student_id===selected?.student_id); const chosen=new Set<string>(courses.map((c:any)=>String(c.course_name))); const semesterGroups=['2-1','2-2','3-1','3-2'].map(scope=>{const [grade,semester]=scope.split('-').map(Number);return {grade,semester,courses:courses.filter((c:any)=>c.target_grade===grade&&c.target_semester===semester).map((c:any)=>c.course_name)};});
 return <><section className="surface panel"><div className="panel-head"><div><h2>학생 신청안 검토</h2><p className="panel-sub">반 전체 신청안을 번호순으로 보고, 수정이 필요한 학생만 처리합니다.</p></div></div><div className="grid-cards teacher-summary">{[['전체',String((data.plans||[]).length),''],['작성 중',String(counts.draft||0),'draft'],['제출 완료',String((counts.submitted||0)+(counts.pending||0)+(counts.confirmed||0)+(counts.recheck_required||0)),'submitted'],['수정 요청',String(counts.revision_requested||0),'revision_requested'],['재제출 완료',String(counts.resubmitted||0),'resubmitted']].map(([label,count,value])=><button className={`metric ${status===value?'selected-metric':''}`} key={label} onClick={()=>setStatus(value)}><span>{label}</span><strong>{count}</strong></button>)}</div><div className="toolbar" style={{marginTop:14}}><div className="field"><label>학생 검색</label><input className="control" value={query} onChange={e=>setQuery(e.target.value)} placeholder="이름 또는 번호"/></div><div className="field"><label>반</label><select className="control" value={classNo} onChange={e=>setClassNo(e.target.value)}><option value="">전체</option>{[...new Set((data.plans||[]).map((p:any)=>p.current_class))].map((v:any)=><option key={v}>{v}</option>)}</select></div><div className="field"><label>차수</label><select className="control" value={round} onChange={e=>setRound(e.target.value)}><option value="">전체</option>{[...new Set((data.plans||[]).map((p:any)=>p.round_number))].map((v:any)=><option key={v}>{v}차</option>)}</select></div><div className="field"><label>제출 상태</label><select className="control" value={status} onChange={e=>setStatus(e.target.value)}><option value="">전체</option>{Object.entries(statusLabels).slice(0,7).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></div><button className={attentionOnly?'primary-btn':'secondary-btn'} onClick={()=>setAttentionOnly(!attentionOnly)}>확인 필요 학생만</button></div><div className="table-wrap" style={{marginTop:14}}><table><thead><tr><th>번호</th><th>이름</th><th>제출 상태</th><th>희망대학 · 학과</th><th>추천과목 경고</th><th>최근 제출·수정</th><th>수정 요청</th><th></th></tr></thead><tbody>{plans.map((p:any)=>{const hasWarning=needsAttention(p);const prefsForPlan=(data.planPreferences||[]).filter((pref:any)=>pref.student_id===p.student_id);return <tr className={hasWarning?'attention':''} key={p.id}><td>{p.current_number}번</td><td><strong>{p.name}</strong></td><td><Badge tone={statusTone(p.status)}>{statusLabels[p.status]}</Badge></td><td>{prefsForPlan.length?prefsForPlan.map((pref:any)=>`${pref.university||'대학 미입력'} / ${pref.department||'학과 미입력'}`).join(', '):'미입력'}</td><td>{hasWarning?<Badge tone="amber">확인 필요</Badge>:<span className="panel-sub">없음</span>}</td><td>{new Date(p.submitted_at||p.updated_at).toLocaleString('ko-KR')}</td><td>{p.status==='revision_requested'?<Badge tone="red">요청됨</Badge>:<span className="panel-sub">-</span>}</td><td><button className="ghost-btn" onClick={()=>setSelectedId(p.id)}>상세 확인</button></td></tr>})}</tbody></table></div>{!plans.length&&<div className="empty" style={{marginTop:12}}>조건에 맞는 학생 신청안이 없습니다.</div>}</section>
 {selected&&<section className="surface panel teacher-detail"><div className="panel-head"><div><h2>{selected.name} 학생 신청안</h2><p className="panel-sub">{selected.entrance_year}년 입학생 · {selected.current_class}반 {selected.current_number}번 · {selected.round_number}차</p></div><Badge tone={statusTone(selected.status)}>{statusLabels[selected.status]}</Badge></div><div className="detail-grid"><div><h3>진로 정보</h3><p><strong>선택 계열</strong><br/>{trackLabels[selected.academic_track]||'아직 미정'}</p><p><strong>관심 진로</strong><br/>{selected.career_goal||'미입력'}</p><p><strong>학생 메모</strong><br/>{selected.counseling_memo||'없음'}</p><strong>희망 대학·학과</strong>{prefs.length?<ul>{prefs.map((p:any)=><li key={p.rank}>{p.rank}순위 · {p.university||'대학 미입력'} / {p.department||'학과 미입력'}</li>)}</ul>:<p>미입력</p>}</div><div><h3>수강신청안</h3>{semesterGroups.map(group=><div className="semester-result" key={`${group.grade}-${group.semester}`}><strong>{semesterLabel(group.grade,group.semester)}</strong><div className="chips">{group.courses.length?group.courses.map((name:string)=><span className="course-chip" key={name}>{name}</span>):<span className="panel-sub">선택 과목 없음</span>}</div></div>)}</div></div><TrackCourseGuide data={data} academicTrack={selected.academic_track||'undecided'} selectedCourses={[...chosen]}/><TeacherRecommendation requirements={reqs} chosen={chosen}/><div className="review-box"><h3>담임 검토</h3>{['submitted','resubmitted','pending','confirmed','recheck_required'].includes(selected.status)?<><p className="panel-sub">문제가 없다면 별도 처리 없이 제출 상태를 그대로 두면 됩니다.</p><div className="field"><label>수정 요청 코멘트</label><textarea className="control" value={comment} onChange={e=>setComment(e.target.value)} placeholder="예: 희망학과 기준으로 화학 관련 과목 선택을 다시 확인해보세요."/></div><button className="primary-btn" style={{marginTop:12}} onClick={review}>수정 요청</button></>:<div className="message warn">현재 신청안은 {statusLabels[selected.status]} 상태입니다. 학생이 제출하면 이곳에서 검토할 수 있습니다.</div>}<NoticeBox notice={notice}/><ReviewHistory rows={(data.planReviews||[]).filter((r:any)=>r.plan_id===selected.id)}/></div></section>}</>;
}

function TeacherRecommendation({requirements,chosen}:{requirements:any[];chosen:Set<string>}) { const exact=requirements.filter(r=>r.match_level==='exact'); const display=exact.length?exact:requirements; const core=[...new Set(display.filter(r=>r.recommendation_type==='core').map(r=>r.course_name))]; const recommended=[...new Set(display.filter(r=>r.recommendation_type==='recommended').map(r=>r.course_name))]; const missingCore=core.filter(x=>!chosen.has(x)); const missingRecommended=recommended.filter(x=>!chosen.has(x)); return <section className="teacher-recommendation"><h3>대학·학과 추천과목 비교</h3>{!requirements.length?<div className="message warn">정확히 일치하는 추천 자료가 없습니다. 자료 없음 / 담임 확인 필요</div>:<><div className="recommendation-grid"><RecommendationBox title="핵심과목" tone="pink" courses={core}/><RecommendationBox title="권장과목" tone="purple" courses={recommended}/><RecommendationBox title="현재 선택한 추천과목" tone="green" courses={[...new Set(display.filter(r=>chosen.has(r.course_name)).map(r=>r.course_name))]}/><RecommendationBox title="미선택 핵심과목" tone="amber" courses={missingCore}/><RecommendationBox title="미선택 권장과목" tone="amber" courses={missingRecommended}/></div>{(missingCore.length||missingRecommended.length)>0&&<div className="message warn">희망 대학/학과 자료 기준으로 확인이 필요한 과목이 있습니다. 자동 판정이 아닌 상담 참고 정보입니다.</div>}<div className="panel-sub">{exact.length?'희망 대학 + 희망 학과 정확 일치 자료를 우선 표시합니다.':'동일 학과 또는 계열 참고자료입니다.'}</div></>}</section>; }
function ReviewHistory({rows}:{rows:any[]}) { return <div className="review-history"><h3>수정 요청·재제출 이력</h3>{rows.length?rows.map(r=><div className="semester-result" key={r.id}><strong>{r.action==='revision_requested'?'수정 요청':r.action==='resubmitted'?'재제출 완료':r.action==='submitted'?'제출 완료':r.action==='confirmed'?'제출 완료(기존 기록)':r.action}</strong><span className="panel-sub"> · {r.actor} · {new Date(r.created_at).toLocaleString('ko-KR')}</span>{r.comment&&<p>{r.comment}</p>}</div>):<p className="panel-sub">아직 수정 요청 이력이 없습니다.</p>}</div>; }

function UploadView({year,session,reload}:{year:number;session:Session;reload:()=>Promise<void>}) { const [round,setRound]=useState(1); const [files,setFiles]=useState<ParsedOfficialFile[]>([]); const [preview,setPreview]=useState<any>(null); const [replaceScopes,setReplaceScopes]=useState<string[]>([]); const [notice,setNotice]=useState<Notice>(null); const [busy,setBusy]=useState(false);
 const choose=async(e:React.ChangeEvent<HTMLInputElement>)=>{setBusy(true);setPreview(null);setNotice(null);try{const parsed=(await Promise.all([...e.target.files||[]].map(parseOfficialWorkbook))).flatMap(splitIntegratedOfficialFile);setFiles(parsed);const integrated=parsed.some(f=>f.warnings.some(w=>w.includes('전교생 통합 파일')));setNotice({type:'success',text:`${parsed.length}개 반·학기 자료를 읽었습니다.${integrated?' 통합 파일은 반별로 자동 분리했습니다.':''} 학년·학기와 반을 확인해주세요.`});}catch(err){setNotice({type:'error',text:err instanceof Error?err.message:'파일을 읽지 못했습니다.'});}finally{setBusy(false);}};
 const update=(i:number,key:keyof ParsedOfficialFile,value:any)=>setFiles(files.map((f,n)=>n===i?{...f,[key]:Number(value)}:f));
 const analyze=async()=>{setBusy(true);try{const result=await api('/api/import',session.token,{method:'POST',body:JSON.stringify({action:'preview',entranceYear:year,roundNumber:round,files})});setPreview(result);setReplaceScopes([]);}catch(e){setNotice({type:'error',text:e instanceof Error?e.message:'분석하지 못했습니다.'});}finally{setBusy(false);}};
 const commit=async()=>{if(!preview)return;if(!window.confirm(`${year}년 입학생 ${round}차 공식 결과로 ${preview.summary.validCount}개 파일을 반영하시겠습니까?`))return;setBusy(true);try{const result=await api('/api/import',session.token,{method:'POST',body:JSON.stringify({action:'commit',entranceYear:year,roundNumber:round,files,replaceScopes})});const savedStudents=(result.applied||[]).reduce((sum:number,item:any)=>sum+Number(item.studentCount||0),0);setNotice({type:result.failed.length?'warn':'success',text:`공식 결과를 저장했습니다. ${result.applied.length}개 자료 · 학생 ${savedStudents}명을 반영했습니다.${result.failed.length?` ${result.failed.length}개는 오류로 제외했습니다.`:''}`});setPreview(null);setFiles([]);await reload();}catch(e){setNotice({type:'error',text:e instanceof Error?e.message:'반영하지 못했습니다.'});}finally{setBusy(false);}};
 return <section className="surface panel"><div className="panel-head"><div><h2>학교 공식 결과 업로드</h2><p className="panel-sub">학생 신청안과 섞이지 않으며, 차수별 공식 최종 결과로 따로 보존됩니다.</p></div><Badge tone="pink">공식 결과</Badge></div><div className="field"><label>저장할 차수</label><div className="segmented">{[1,2,3].map(n=><button key={n} className={round===n?'active':''} onClick={()=>{setRound(n);setPreview(null);}}>{n}차 결과로 저장</button>)}</div></div><div className="upload-drop" style={{marginTop:14}}><div><FileSpreadsheet size={36} color="#6a5acd"/><p><strong>학년·반·학기별 엑셀 파일을 여러 개 선택하세요.</strong></p><input type="file" accept=".xlsx,.xls" multiple onChange={choose}/></div></div><NoticeBox notice={notice}/>{files.map((f,i)=><div className="file-card" key={`${f.fileName}-${i}`}><div className="file-title"><span>{f.fileName}</span>{f.error?<Badge tone="red">오류</Badge>:<Badge tone="green">{f.students.length}명</Badge>}</div><div className="file-settings"><div className="field"><label>현재 반</label><input className="control" inputMode="numeric" value={f.currentClass||''} onChange={e=>update(i,'currentClass',e.target.value)}/></div><div className="field"><label>대상 학년</label><select className="control" value={f.targetGrade||''} onChange={e=>update(i,'targetGrade',e.target.value)}><option value="">선택</option><option value="2">2학년</option><option value="3">3학년</option></select></div><div className="field"><label>대상 학기</label><select className="control" value={f.targetSemester||''} onChange={e=>update(i,'targetSemester',e.target.value)}><option value="">선택</option><option value="1">1학기</option><option value="2">2학기</option></select></div></div>{f.warnings?.map(w=><div className="message warn" key={w}>{w}</div>)}</div>)}{files.length>0&&!preview&&<button className="primary-btn" disabled={busy} style={{marginTop:14}} onClick={analyze}>{busy?'분석 중...':'업로드 전 분석'}</button>}{preview&&<div style={{marginTop:18}}><div className="grid-cards"><div className="metric"><span>업로드 파일</span><strong>{preview.summary.fileCount}</strong></div><div className="metric"><span>신규</span><strong>{preview.summary.newCount}</strong></div><div className="metric alert"><span>교체 예정</span><strong>{preview.summary.replacementCount}</strong></div><div className="metric alert"><span>오류</span><strong>{preview.summary.errorCount}</strong></div></div>{preview.preview.map((f:any)=><div className="file-card" key={f.scope}><div className="file-title"><span>{f.currentClass}반 · {semesterLabel(f.targetGrade,f.targetSemester)} · {f.studentCount}명</span><Badge tone={f.valid?(f.existing?'amber':'green'):'red'}>{f.valid?(f.existing?'기존 자료 있음':'신규'):'오류'}</Badge></div>{f.existing&&<label className="check-row"><input type="checkbox" checked={replaceScopes.includes(f.scope)} onChange={e=>setReplaceScopes(e.target.checked?[...replaceScopes,f.scope]:replaceScopes.filter(x=>x!==f.scope))}/><span><strong>기존 자료가 있습니다.</strong><br/>해당 반/학기 자료를 교체합니다. 이전 업로드 기록은 남습니다.</span></label>}</div>)}<div className="message warn">최종 확인: {year}년 입학생 · {round}차 · 정상 파일 {preview.summary.validCount}개 · 학생 행 {preview.summary.studentCount}개</div><button className="primary-btn" disabled={busy||preview.preview.some((f:any)=>f.existing&&!replaceScopes.includes(f.scope))} onClick={commit}>최종 반영</button></div>}</section>; }

function VerificationView({data,session,reload}:{data:any;session:Session;reload:()=>Promise<void>}) {
  const [kind,setKind]=useState<'approved'|'rounds'>('approved');
  const [filter,setFilter]=useState('all');
  const [query,setQuery]=useState('');
  const [notice,setNotice]=useState<Notice>(null);
  const source=kind==='approved'?(data.validations||[]):(data.comparisons||[]);
  const rows=source.filter((r:any)=>{const status=kind==='approved'?r.validationStatus:r.status;const attention=kind==='approved'?status!=='일치'||r.reviewStatus==='student_check':r.review==='확인 필요';return (filter==='all'||filter==='changed'&&status!=='변경 없음'&&status!=='일치'&&!status.includes('자료')&&!status.includes('등장')||filter==='same'&&(status==='변경 없음'||status==='일치')||filter==='missing'&&(status==='승인안 없음'||status==='실제 결과 없음'||status.includes('자료에서'))||filter==='attention'&&attention||filter==='confirmed'&&kind==='approved'&&r.reviewStatus==='confirmed')&&(!query||`${r.name} ${r.currentClass} ${r.currentNumber}`.includes(query));});
  const confirmItems=async(items:any[])=>{try{await api('/api/action',session.token,{method:'POST',body:JSON.stringify({action:'reviewVerification',items:items.map(r=>({studentId:r.studentId,roundNumber:r.round,targetGrade:r.targetGrade,targetSemester:r.targetSemester,status:'confirmed'}))})});setNotice({type:'success',text:`${items.length}건을 확인 완료로 처리했습니다.`});await reload();}catch(e){setNotice({type:'error',text:e instanceof Error?e.message:'처리하지 못했습니다.'});}};
  const matching=(data.validations||[]).filter((r:any)=>r.validationStatus==='일치'&&r.reviewStatus==='unreviewed');
  const [classFilter,setClassFilter]=useState('');
  const classOptions=[...new Set(source.map((r:any)=>String(r.currentClass)).filter(Boolean))].sort((a:any,b:any)=>Number(a)-Number(b));
  const sortedRows=rows.filter((r:any)=>!classFilter||String(r.currentClass)===classFilter).sort((a:any,b:any)=>a.currentClass-b.currentClass||a.currentNumber-b.currentNumber||String(a.name).localeCompare(String(b.name),'ko'));
  const groupedStudents=new Map<string,any>(); for(const row of sortedRows){const key=`${row.entranceYear||''}:${row.currentClass}:${row.currentNumber}:${row.name}`;const group=groupedStudents.get(key)||{...row,semesters:[]};group.semesters.push(row);groupedStudents.set(key,group);} const students=[...groupedStudents.values()];
  const studentSummary=students.reduce((summary:any,student:any)=>{const statuses=student.semesters.map((item:any)=>kind==='approved'?item.validationStatus:item.status);const reviews=student.semesters.map((item:any)=>kind==='approved'?item.reviewStatus:'unreviewed');summary.total++;if(statuses.some((item:string)=>item==='승인안 없음'))summary.missing++;else if(statuses.some((item:string)=>item!=='일치'&&item!=='변경 없음'&&!item.includes('자료')&&!item.includes('등장')))summary.changed++;else summary.same++;if(statuses.some((item:string)=>item!=='일치'&&item!=='변경 없음'))summary.attention++;if(kind==='approved'&&reviews.every((item:string)=>item==='confirmed'))summary.confirmed++;return summary;},{total:0,same:0,changed:0,missing:0,attention:0,confirmed:0});
  return <section className="surface panel"><div className="panel-head"><div><h2>공식 결과 검증</h2><p className="panel-sub">학생은 한 번만 표시하고, 대상 학기별 검증 결과를 아래에 묶어 보여줍니다.</p></div>{kind==='approved'&&matching.length>0&&<button className="secondary-btn" onClick={()=>confirmItems(matching)}>일치 학생 일괄 확인</button>}</div>
    <div className="grid-cards verification-summary"><button className={`metric ${filter==='all'?'selected-metric':''}`} onClick={()=>setFilter('all')}><span>전체 학생</span><strong>{studentSummary.total}</strong></button><button className={`metric ${filter==='same'?'selected-metric':''}`} onClick={()=>setFilter('same')}><span>일치</span><strong>{studentSummary.same}</strong></button><button className={`metric ${filter==='changed'?'selected-metric':''}`} onClick={()=>setFilter('changed')}><span>변경 있음</span><strong>{studentSummary.changed}</strong></button><button className={`metric ${filter==='missing'?'selected-metric':''}`} onClick={()=>setFilter('missing')}><span>승인안·공식 결과 없음</span><strong>{studentSummary.missing}</strong></button><button className={`metric alert ${filter==='attention'?'selected-metric':''}`} onClick={()=>setFilter('attention')}><span>확인 필요</span><strong>{studentSummary.attention}</strong></button><button className={`metric ${filter==='confirmed'?'selected-metric':''}`} onClick={()=>kind==='approved'&&setFilter('confirmed')}><span>확인 완료</span><strong>{studentSummary.confirmed}</strong></button></div>
    <div className="segmented" style={{marginBottom:12}}><button className={kind==='approved'?'active':''} onClick={()=>setKind('approved')}>담임 승인안 ↔ 공식 결과</button><button className={kind==='rounds'?'active':''} onClick={()=>setKind('rounds')}>1차 ↔ 2차 공식 결과</button></div>
    <div className="toolbar"><div className="segmented">{[['all','전체'],['changed','불일치·변경'],['same','일치·변경 없음'],['missing','승인안·공식 결과 없음'],['attention','확인 필요']].map(([v,l])=><button key={v} className={filter===v?'active':''} onClick={()=>setFilter(v)}>{l}</button>)}</div><div className="class-filter-chips" aria-label="반별 필터"><button className={!classFilter?'active':''} onClick={()=>setClassFilter('')}>전체</button>{classOptions.map((n:any)=><button key={n} className={classFilter===n?'active':''} onClick={()=>setClassFilter(n)}>{n}반</button>)}</div><div className="field"><label className="sr-only">학생 검색</label><input className="control" value={query} onChange={e=>setQuery(e.target.value)} placeholder="이름 또는 번호 검색"/></div></div><NoticeBox notice={notice}/>
    <div className="verification-groups" style={{marginTop:14}}>{students.map((student:any)=><article className="verification-group" key={`${student.currentClass}-${student.currentNumber}-${student.name}`}><header><strong>{student.name}</strong><span>{student.currentClass}반 {student.currentNumber}번</span></header><div className="table-wrap"><table><thead><tr><th>대상 학기</th><th>{kind==='approved'?'담임 승인안':'1차 신청 과목'}</th><th>{kind==='approved'?'공식 결과':'2차 신청 과목'}</th><th>검증 상태</th><th>확인</th></tr></thead><tbody>{student.semesters.sort((a:any,b:any)=>a.targetGrade-b.targetGrade||a.targetSemester-b.targetSemester).map((r:any,i:number)=>{const status=kind==='approved'?r.validationStatus:r.status;const left=kind==='approved'?r.approvedCourses:r.firstCourses;const right=kind==='approved'?r.officialCourses:r.secondCourses;return <tr key={`${r.targetGrade}-${r.targetSemester}-${i}`} className={status==='일치'||status==='변경 없음'?'':'attention'}><td>{kind==='approved'&&`${r.round}차 · `}{semesterLabel(r.targetGrade,r.targetSemester)}</td><td><CourseTags courses={left}/></td><td><CourseTags courses={right}/></td><td><Badge tone={statusTone(status)}>{verificationLabel(status)}</Badge>{r.removed?.length>0&&<div className="panel-sub">삭제: <CourseTags courses={r.removed}/></div>}{r.added?.length>0&&<div className="panel-sub">추가: <CourseTags courses={r.added}/></div>}</td><td>{kind==='approved'?<div className="toolbar"><Badge tone={r.reviewStatus==='confirmed'?'green':'gray'}>{r.reviewStatus==='confirmed'?'확인 완료':'미확인'}</Badge>{r.reviewStatus!=='confirmed'&&<button className="ghost-btn" onClick={()=>confirmItems([r])}>확인 완료</button>}</div>:r.review}</td></tr>;})}</tbody></table></div></article>)}</div>{!students.length&&<div className="empty" style={{marginTop:12}}>조건에 맞는 학생이 없습니다.</div>}
  </section>;
}

const referenceHeaderAliases: Record<string,string[]> = {
  university:['대학명','대학교','대학'], region:['지역','권역','소재지'], track:['계열','계열명'], department:['모집단위','학과','학부','모집단위/학과','대표 모집단위'], coreCourses:['핵심과목','핵심 과목','필수과목'], recommendedCourses:['권장과목','권장 과목','추천과목'], note:['비고','참고','메모'], courseName:['과목명','과목'], area:['과목군','교과 영역','교과영역','영역'], subjectArea:['과목 영역','과목영역','교과 영역','교과영역','영역'], targetGrade:['대상 학년','대상학년','학년'], targetSemester:['대상 학기','대상학기','학기'], overview:['과목 설명','과목설명','과목 개요','개요'], offered:['선택 가능 여부','선택가능여부','개설 여부','개설여부','선택 가능'], credits:['이수단위','학점','단위'], selectionType:['선택과목 유형','선택 분류','선택과목분류']
};
const trackHeaderAliases: Record<string,string[]> = {
  // 매트릭스 자료는 '모집단위 / 계열', '모집단위 / 학과'처럼 두 줄 제목을
  // 함께 읽어야 한다. 일반 과목명 별칭은 과목 열을 데이터 열로 오인하므로 제외한다.
  track:['계열','계열명'], department:['학과','학부','모집단위/학과','대표 모집단위','모집단위'], note:['비고','참고','메모']
};
function parseReferenceRows(rows:any[][]){const headerIndex=rows.findIndex(row=>row.filter(Boolean).length>=2);if(headerIndex<0)return {rows:[],error:'열 제목 행을 찾지 못했습니다.'};const headers=rows[headerIndex].map(normalizeHeader);const result=rows.slice(headerIndex+1).filter(row=>row.some(cell=>String(cell||'').trim())).map(row=>{const item:any={};Object.entries(referenceHeaderAliases).forEach(([key,aliases])=>{const index=headers.findIndex(header=>aliases.some(alias=>normalizeHeader(alias)===header));if(index>=0)item[key]=String(row[index]??'').trim();});return item;});return {rows:result,error:''};}

function ReferenceUploadManager({_year,data,session,reload,onNotice}:{_year:number;data:any;session:Session;reload:()=>Promise<void>;onNotice:(notice:Notice)=>void}){
  const [tab,setTab]=useState<'university'|'school'|'history'>('university'); const [type,setType]=useState<'university_regional'|'university_track'|'school_course'>('university_regional'); const [criteriaYear,setCriteriaYear]=useState('2028'); const [file,setFile]=useState<File|null>(null); const [rows,setRows]=useState<any[]>([]); const [analysis,setAnalysis]=useState<any>(null); const [busy,setBusy]=useState(false);
  const selectFile=async(next:File|null)=>{setFile(next);setAnalysis(null);setRows([]);if(!next)return;try{const workbook=XLSX.read(await next.arrayBuffer(),{type:'array'});const sheet=workbook.Sheets[workbook.SheetNames[0]];const matrix=XLSX.utils.sheet_to_json<any[]>(sheet,{header:1,defval:'',raw:false});const parsed=parseReferenceRows(matrix);if(parsed.error)throw new Error(parsed.error);setRows(parsed.rows);onNotice({type:'success',text:`파일을 읽었습니다. ${parsed.rows.length}개 행을 분석할 준비가 되었습니다. 아직 저장되지 않았습니다.`});}catch(e){onNotice({type:'error',text:e instanceof Error?e.message:'파일을 읽지 못했습니다.'});}};
  const analyze=async()=>{if(!file||!rows.length){onNotice({type:'warn',text:'먼저 형식이 맞는 엑셀 파일을 선택해주세요.'});return;}setBusy(true);try{setAnalysis(await api('/api/reference-import',session.token,{method:'POST',body:JSON.stringify({action:'preview',referenceType:type,criteriaYear:Number(criteriaYear),fileName:file.name,rows})}));}catch(e){onNotice({type:'error',text:e instanceof Error?e.message:'분석하지 못했습니다.'});}finally{setBusy(false);}};
  const save=async()=>{if(!analysis||!file)return;const existing=analysis.existing||[];if(existing.length&&!window.confirm(`같은 ${criteriaYear}학년도 적용 자료가 있습니다. 기존 자료는 이력으로 남기고 새 자료로 교체할까요?`))return;setBusy(true);try{const result=await api('/api/reference-import',session.token,{method:'POST',body:JSON.stringify({action:'commit',referenceType:type,criteriaYear:Number(criteriaYear),fileName:file.name,rows,replaceUploadIds:existing.map((item:any)=>item.id)})});onNotice({type:'success',text:`기준자료를 저장했습니다. ${result.savedCount}개 항목을 반영했습니다.${result.replacedCount?` 기존 ${result.replacedCount}개 자료는 이력으로 보존했습니다.`:''}`});setFile(null);setRows([]);setAnalysis(null);await reload();}catch(e){onNotice({type:'error',text:e instanceof Error?e.message:'저장하지 못했습니다.'});}finally{setBusy(false);}};
  const deactivate=async(uploadId:string)=>{if(!window.confirm('이 자료의 적용을 해제할까요? 삭제하지 않고 업로드 이력은 남겨둡니다.'))return;try{await api('/api/reference-import',session.token,{method:'POST',body:JSON.stringify({action:'deactivate',uploadId})});onNotice({type:'success',text:'자료 적용을 해제했습니다. 업로드 이력은 보존됩니다.'});await reload();}catch(e){onNotice({type:'error',text:e instanceof Error?e.message:'적용을 해제하지 못했습니다.'});}};
  const currentType=tab==='school'?'school_course':type; const history=(data.referenceUploads||[]).filter((item:any)=>tab==='history'||item.reference_type===currentType); const labels:any={university_regional:'권역별 대학별 권장과목',university_track:'계열별 대표 모집단위 반영과목',school_course:'학교 실제 선택 가능 과목 안내'};
  return <section className="surface panel"><div className="panel-head"><div><h2>기준자료 관리</h2><p className="panel-sub">파일을 선택한 뒤 분석·미리보기를 거쳐 최종 저장합니다. 선택만으로는 어떤 자료도 저장되지 않습니다.</p></div><Badge tone="purple">안전한 업로드</Badge></div><div className="segmented" style={{marginBottom:14}}><button className={tab==='university'?'active':''} onClick={()=>setTab('university')}>대학별 핵심·권장과목</button><button className={tab==='school'?'active':''} onClick={()=>setTab('school')}>학교 실제 선택 가능 과목 안내</button><button className={tab==='history'?'active':''} onClick={()=>setTab('history')}>업로드 이력</button></div>{tab==='history'?<div className="description-list">{history.map((item:any)=><div className="file-card" key={item.id}><div className="file-title"><span>{labels[item.reference_type]}</span><Badge tone={item.active?'green':'gray'}>{item.active?'현재 적용':'이력 보관'}</Badge></div><p className="panel-sub">{item.criteria_year}학년도 · {item.file_name} · {item.row_count}건 · {item.created_at}</p>{item.active&&<button className="ghost-btn" onClick={()=>deactivate(item.id)}>적용 해제</button>}</div>)}{!history.length&&<div className="empty">아직 업로드 이력이 없습니다.</div>}</div>:<><div className="form-grid"><div className="field"><label>기준학년도</label><input className="control" inputMode="numeric" value={criteriaYear} onChange={e=>setCriteriaYear(e.target.value)}/></div>{tab==='university'&&<div className="field"><label>자료 유형</label><select className="control" value={type} onChange={e=>{setType(e.target.value as any);setAnalysis(null);}}><option value="university_regional">권역별 대학별 권장과목</option><option value="university_track">계열별 대표 모집단위 반영과목</option></select></div>}<div className="field full"><label>엑셀 파일</label><input className="control" type="file" accept=".xlsx,.xls" onChange={e=>selectFile(e.target.files?.[0]||null)}/><p className="panel-sub">{tab==='school'?'과목명, 과목군/영역, 대상 학년·학기, 과목 설명, 선택 가능 여부, 이수단위, 비고 열을 인식합니다.':'대학명, 지역/권역, 계열, 모집단위/학과, 핵심과목, 권장과목, 비고 열을 인식합니다.'}</p></div></div><div className="toolbar"><button className="secondary-btn" disabled={!file||busy} onClick={analyze}>{busy?'분석 중...':'파일 분석·미리보기'}</button>{analysis&&<button className="primary-btn" disabled={busy||!analysis.summary.validCount||(referenceType==='university_track'&&(!analysis.summary.relationshipCount||analysis.summary.errorCount>0))} onClick={save}>공식 기준자료로 저장</button>}</div>{analysis&&<div className="message warn" style={{marginTop:14}}><strong>분석 결과</strong><br/>전체 {analysis.summary.totalCount}행 · 저장 가능 {analysis.summary.validCount}행 · 확인 필요 {analysis.summary.errorCount}행{analysis.existing?.length?<> <br/>현재 적용 중인 같은 기준연도 자료 {analysis.existing.length}개가 있습니다. 저장 시 교체 여부를 다시 확인합니다.</>:null}</div>} {analysis?.summary?.sample?.length?<div className="description-list" style={{marginTop:12}}>{analysis.summary.sample.map((item:any,index:number)=><div className="file-card" key={index}><div className="file-title"><span>{tab==='school'?item.courseName:`${item.university||'계열 자료'} · ${item.department||''}`}</span></div><p className="panel-sub">{tab==='school'?`${item.area||'영역 미지정'} · ${item.targetGrade||'?'}학년 ${item.targetSemester||'?'}학기 · ${item.offered||'선택 가능 여부 미지정'}`:`핵심: ${item.coreCourses||'-'} / 권장: ${item.recommendedCourses||'-'}`}</p></div>)}</div>:null}</>}</section>;
}

// 이전 업로드 화면은 기존 세션에서 열린 화면의 상태 호환을 위해 남겨두며, 새 화면은 아래 V2를 사용합니다.
void ReferenceUploadManager;

const referenceFields = [
  ['track','계열'],['region','지역/권역'],['university','대학명'],['department','모집단위/학과'],['coreCourses','핵심과목'],['recommendedCourses','권장과목'],['courseName','과목명'],['area','과목군/영역'],['targetGrade','대상 학년'],['targetSemester','대상 학기'],['overview','과목 설명'],['offered','선택 가능 여부'],['credits','이수단위/학점'],['selectionType','선택과목 유형'],['note','비고']
] as const;
function ReferenceUploadManagerV2({data,session,reload,onNotice}:{data:any;session:Session;reload:()=>Promise<void>;onNotice:(notice:Notice)=>void}) {
  const [tab,setTab] = useState<'university'|'school'|'history'>('university');
  const [type,setType] = useState<'university_regional'|'university_track'>('university_regional');
  const [criteriaYear,setCriteriaYear] = useState('2028');
  const [file,setFile] = useState<File|null>(null); const [sheetRows,setSheetRows] = useState<any[][]>([]); const [headerStart,setHeaderStart] = useState(0); const [headerEnd,setHeaderEnd] = useState(0); const [mapping,setMapping] = useState<Record<string,number>>({});
  const [analysis,setAnalysis] = useState<any>(null); const [busy,setBusy] = useState(false); const [query,setQuery] = useState(''); const [filter,setFilter] = useState({region:'',track:'',grade:'',semester:'',area:''});
  const referenceType = tab==='school' ? 'school_course' : type;
  const columns = useMemo(() => compositeHeaders(sheetRows,headerStart,headerEnd),[sheetRows,headerStart,headerEnd]);
  const aliases = referenceType==='university_track' ? trackHeaderAliases : referenceHeaderAliases;
  const matrixCourseColumnCount = useMemo(() => referenceType==='university_track' ? matrixCourseColumns(columns,mapping).length : 0,[referenceType,columns,mapping]);
  const requiredKeys = referenceType==='university_regional' ? ['university','department'] : referenceType==='university_track' ? ['department'] : ['courseName'];
  const missingRequiredHeaders = requiredKeys.filter((key) => mapping[key] === undefined || mapping[key] < 0).concat(referenceType==='university_regional' && (mapping.coreCourses ?? -1) < 0 && (mapping.recommendedCourses ?? -1) < 0 ? ['핵심과목 또는 권장과목'] : []);
  const records = useMemo(() => {
    if (!sheetRows.length || !columns.length) return [] as any[];
    const mapped = (row:any[], key:string) => { const index=mapping[key] ?? -1; return index >= 0 ? String(row[index] ?? '').trim() : ''; };
    return sheetRows.slice(headerEnd+1).map((row, rowIndex) => ({ row, rowIndex })).filter(({row}) => row.some((cell) => String(cell || '').trim())).map(({row,rowIndex}) => {
      const item:any={}; referenceFields.forEach(([key])=>item[key]=mapped(row,key));
      if (referenceType==='university_track') item.matrixCourses = matrixCoursesFromRow(columns,mapping,row,item.area||'');
      item.sourceRowNumber = headerEnd + rowIndex + 2;
      return item;
    });
  },[sheetRows,headerEnd,columns,mapping,referenceType]);
  const applyHeaderRange=(start:number,end:number)=>{const nextColumns=compositeHeaders(sheetRows,start,end);const detected=mapHeaderColumns(nextColumns,aliases);setHeaderStart(start);setHeaderEnd(end);setMapping(detected);setAnalysis(null);};
  const selectFile=async(next:File|null)=>{setFile(next);setSheetRows([]);setAnalysis(null);if(!next)return;try{const workbook=XLSX.read(await next.arrayBuffer(),{type:'array'});const worksheet=workbook.Sheets[workbook.SheetNames[0]];const raw=XLSX.utils.sheet_to_json<any[]>(worksheet,{header:1,defval:'',raw:false});const matrix=expandMergedCells(raw,(worksheet['!merges']||[]) as any);const detected=detectHeaderRange(matrix,aliases,25,referenceType==='university_track');const mapped=mapHeaderColumns(detected.headers,aliases);setSheetRows(matrix);setHeaderStart(detected.start);setHeaderEnd(detected.end);setMapping(mapped);onNotice({type:'success',text:`파일을 읽었습니다. ${detected.start+1}~${detected.end+1}행을 다중 열 제목으로 인식했습니다. 아직 저장되지 않았습니다.`});}catch(e){console.error('기준자료 파일 분석 실패',e);onNotice({type:'error',text:'파일을 분석하는 중 오류가 발생했습니다. 파일 구조를 확인하거나 다시 시도해주세요.'});}};
  const analyze=async()=>{if(!file||!records.length){onNotice({type:'warn',text:'파일과 열 매핑을 먼저 확인해주세요.'});return;}if(missingRequiredHeaders.length){onNotice({type:'error',text:`필수 열을 찾지 못했습니다: ${missingRequiredHeaders.join(', ')}. 헤더 범위와 열 매핑을 확인해주세요.`});return;}setBusy(true);try{const result=await api('/api/reference-import',session.token,{method:'POST',body:JSON.stringify({action:'preview',referenceType,criteriaYear:Number(criteriaYear),fileName:file.name,rows:records,matrixCourseColumnCount})});setAnalysis(result);}catch(e){onNotice({type:'error',text:e instanceof Error?e.message:'분석하지 못했습니다.'});}finally{setBusy(false);}};
  const save=async()=>{if(!analysis||!file)return;const existing=analysis.existing||[];if(existing.length&&!window.confirm(`${criteriaYear}학년도 ${type==='university_regional'?'대학별 핵심·권장과목':type==='university_track'?'계열별 대표 모집단위':'학교 실제 선택 가능 과목 안내'} 자료가 ${existing.length}개 있습니다. 기존 ${existing.reduce((sum:number,item:any)=>sum+Number(item.row_count||0),0)}건은 이력으로 보존하고 새 ${analysis.summary.validCount}건으로 교체할까요?`))return;setBusy(true);try{const result=await api('/api/reference-import',session.token,{method:'POST',body:JSON.stringify({action:'commit',referenceType,criteriaYear:Number(criteriaYear),fileName:file.name,rows:records,matrixCourseColumnCount,replaceUploadIds:existing.map((item:any)=>item.id)})});onNotice({type:'success',text:`저장 완료: ${result.savedCount}건을 반영했습니다. 오류 ${analysis.summary.errorCount}건은 저장하지 않았습니다.`});setAnalysis(null);setFile(null);setSheetRows([]);await reload();}catch(e){onNotice({type:'error',text:e instanceof Error?e.message:'저장하지 못했습니다.'});}finally{setBusy(false);}};
  const deactivate=async(id:string)=>{if(!window.confirm('현재 적용을 해제할까요? 파일 이력과 기존 데이터 기록은 삭제하지 않습니다.'))return;try{await api('/api/reference-import',session.token,{method:'POST',body:JSON.stringify({action:'deactivate',uploadId:id})});onNotice({type:'success',text:'자료 적용을 해제했습니다. 업로드 이력은 보존됩니다.'});await reload();}catch(e){onNotice({type:'error',text:e instanceof Error?e.message:'해제하지 못했습니다.'});}};
  const uploads=(data.referenceUploads||[]); const activeUploads=uploads.filter((item:any)=>item.active); const universityRows=(data.universityReferenceEntries||[]).filter((item:any)=>!filter.region||item.region===filter.region).filter((item:any)=>!filter.track||item.track===filter.track).filter((item:any)=>!query||`${item.university} ${item.department} ${item.region} ${item.track}`.includes(query)); const trackRows=(data.trackReferenceEntries||[]).filter((item:any)=>!filter.track||item.track===filter.track).filter((item:any)=>!query||`${item.department} ${item.track} ${item.course_name}`.includes(query)); const schoolRows=(data.schoolCourseGuides||[]).filter((item:any)=>(!filter.grade||String(item.target_grade)===filter.grade)&&(!filter.semester||String(item.target_semester)===filter.semester)&&(!filter.area||item.area===filter.area)&&(!query||`${item.course_name} ${item.area}`.includes(query)));
  const visibleRows=tab==='school'?schoolRows:type==='university_regional'?universityRows:trackRows;
  return <section className="surface panel"><div className="panel-head"><div><h2>기준자료 관리</h2><p className="panel-sub">선택한 파일은 분석과 미리보기를 마친 뒤 ‘최종 저장’을 눌러야만 반영됩니다.</p></div><Badge tone="purple">적용 중 {activeUploads.length}개</Badge></div><div className="segmented" style={{marginBottom:14}}><button className={tab==='university'?'active':''} onClick={()=>setTab('university')}>대학별 핵심·권장과목</button><button className={tab==='school'?'active':''} onClick={()=>setTab('school')}>학교 실제 선택 가능 과목 안내</button><button className={tab==='history'?'active':''} onClick={()=>setTab('history')}>업로드 이력</button></div>{tab==='history'?<div className="description-list">{uploads.map((item:any)=><div className="file-card" key={item.id}><div className="file-title"><span>{item.criteria_year}학년도 · {item.reference_type==='university_regional'?'대학별 핵심·권장과목':item.reference_type==='university_track'?'계열별 대표 모집단위':'학교 실제 선택 가능 과목 안내'}</span><Badge tone={item.active?'green':'gray'}>{item.active?'현재 적용':'이력 보관'}</Badge></div><p className="panel-sub">{item.file_name} · {item.row_count}건 저장 · 오류 {item.failed_count||0}건 · {item.created_at} · {item.uploaded_by}</p>{item.active&&<button className="ghost-btn" onClick={()=>deactivate(item.id)}>적용 해제</button>}</div>)}{!uploads.length&&<div className="empty">아직 업로드 이력이 없습니다.</div>}</div>:<><div className="form-grid"><div className="field"><label>기준학년도</label><input className="control" inputMode="numeric" value={criteriaYear} onChange={e=>{setCriteriaYear(e.target.value);setAnalysis(null);}}/></div>{tab==='university'&&<div className="field"><label>자료 종류</label><select className="control" value={type} onChange={e=>{setType(e.target.value as any);setAnalysis(null);}}><option value="university_regional">대학별 핵심·권장과목</option><option value="university_track">계열별 대표 모집단위 반영과목</option></select></div>}<div className="field full"><label>엑셀 파일</label><input className="control" type="file" accept=".xlsx,.xls" onChange={e=>selectFile(e.target.files?.[0]||null)}/></div></div>{sheetRows.length>0&&<><div className="form-grid" style={{marginTop:12}}><div className="field"><label>헤더 시작 행</label><select className="control" value={headerStart} onChange={e=>applyHeaderRange(Number(e.target.value),Math.max(Number(e.target.value),headerEnd))}>{sheetRows.slice(0,Math.min(20,sheetRows.length)).map((row,index)=><option key={index} value={index}>{index+1}행 · {row.filter((cell:any)=>String(cell||'').trim()).slice(0,4).join(' / ')||'빈 행'}</option>)}</select></div><div className="field"><label>헤더 마지막 행</label><select className="control" value={headerEnd} onChange={e=>applyHeaderRange(Math.min(headerStart,Number(e.target.value)),Number(e.target.value))}>{sheetRows.slice(headerStart,Math.min(20,sheetRows.length)).map((row,index)=>{const rowIndex=headerStart+index;return <option key={rowIndex} value={rowIndex}>{rowIndex+1}행 · {row.filter((cell:any)=>String(cell||'').trim()).slice(0,4).join(' / ')||'빈 행'}</option>})}</select></div></div><div className="form-grid" style={{marginTop:10}}>{referenceFields.filter(([key])=>tab==='school'?['courseName','area','targetGrade','targetSemester','overview','offered','credits','selectionType','note'].includes(key):type==='university_regional'?['track','region','university','department','coreCourses','recommendedCourses','note'].includes(key):['track','department','area','coreCourses','recommendedCourses','note'].includes(key)).map(([key,label])=><div className="field" key={key}><label>{label}</label><select className="control" value={mapping[key] ?? -1} onChange={e=>{setMapping({...mapping,[key]:Number(e.target.value)});setAnalysis(null);}}><option value={-1}>선택 안 함</option>{columns.map((column,index)=><option key={`${column}-${index}`} value={index}>{column||`열 ${index+1}`}</option>)}</select></div>)}</div>{type==='university_track'&&tab==='university'&&<div className="message warn" style={{marginTop:10}}>매트릭스 형식 파일은 위에 매핑하지 않은 열을 세부 과목명으로 보고, 각 셀의 대학명을 과목 반영 대학 목록으로 저장합니다.</div>}<div className="toolbar" style={{marginTop:12}}><button className="secondary-btn" disabled={busy} onClick={analyze}>{busy?'분석 중...':'파일 분석·미리보기'}</button>{analysis&&<button className="primary-btn" disabled={busy||!analysis.summary.validCount||(referenceType==='university_track'&&(!analysis.summary.relationshipCount||analysis.summary.errorCount>0))} onClick={save}>최종 저장</button>}</div></>}{analysis&&<ReferencePreviewRows rows={analysis.summary.sample} type={referenceType}/>} {analysis&&referenceType==='university_track'&&<TrackAnalysisSummary analysis={analysis}/>} {analysis&&referenceType!=='university_track'&&<div className="message warn" style={{marginTop:14}}><strong>미리보기</strong><br/>자료 유형: {referenceType} · 기준학년도: {criteriaYear} · 파일: {file?.name}<br/>{referenceType==='university_track'?<>모집단위 행 {analysis.summary.validCount}건 · 인식된 과목 열 {analysis.summary.matrixCourseColumnCount||0}건 · 반영 대학이 있는 과목 셀 {analysis.summary.matrixCourseCount||0}건 · 생성될 과목-대학 관계 {analysis.summary.relationshipCount||0}건<br/>자동 제외 행 {analysis.summary.autoExcludedCount||0}건 · 실제 오류 행 {analysis.summary.errorCount}건</>:<>인식 행 {analysis.summary.totalCount}건 · 저장 가능 {analysis.summary.validCount}건 · 오류 {analysis.summary.errorCount}건</>}{analysis.existing?.length?<><br/>기존 적용 자료 {analysis.existing.length}개 · 기존 {analysis.existing.reduce((sum:number,item:any)=>sum+Number(item.row_count||0),0)}건</>:null}</div>}{referenceType!=='university_track'&&analysis?.invalidRows?.length?<div className="message error" style={{marginTop:10}}>저장 제외 행: {analysis.invalidRows.map((row:any)=>`${row.rowNumber}행(필수값 누락)`).join(', ')}</div>:null}</>}<div className="toolbar" style={{marginTop:18}}><div className="field"><label className="sr-only">검색</label><input className="control" value={query} onChange={e=>setQuery(e.target.value)} placeholder="대학·학과·과목 검색"/></div>{tab==='school'?<><select className="control" value={filter.grade} onChange={e=>setFilter({...filter,grade:e.target.value})}><option value="">전체 학년</option><option value="2">2학년</option><option value="3">3학년</option></select><select className="control" value={filter.semester} onChange={e=>setFilter({...filter,semester:e.target.value})}><option value="">전체 학기</option><option value="1">1학기</option><option value="2">2학기</option></select></>:<><select className="control" value={filter.region} onChange={e=>setFilter({...filter,region:e.target.value})}><option value="">전체 권역</option>{[...new Set((data.universityReferenceEntries||[]).map((item:any)=>item.region).filter(Boolean))].map((item:any)=><option key={item}>{item}</option>)}</select><select className="control" value={filter.track} onChange={e=>setFilter({...filter,track:e.target.value})}><option value="">전체 계열</option>{[...new Set([...(data.universityReferenceEntries||[]).map((item:any)=>item.track),...(data.trackReferenceEntries||[]).map((item:any)=>item.track)].filter(Boolean))].map((item:any)=><option key={item}>{item}</option>)}</select></>}</div><div className="description-list">{visibleRows.slice(0,40).map((item:any,index:number)=><div className="file-card" key={item.id||index}><div className="file-title"><span>{tab==='school'?item.course_name:type==='university_regional'?`${item.university} · ${item.department}`:`${item.department} · ${item.course_name}`}</span><Badge tone="purple">{tab==='school'?`${item.target_grade||'?'}학년 ${item.target_semester||'?'}학기`:item.recommendation_type==='core'?'핵심':'권장'}</Badge></div><p className="panel-sub">{tab==='school'?`${item.area||'영역 미지정'} · ${item.overview||'설명 없음'}`:type==='university_regional'?`핵심: ${item.core_courses_raw||'-'} / 권장: ${item.recommended_courses_raw||'-'}`:`${item.track||'계열 미지정'} · ${item.subject_area||'영역 미지정'}`}</p></div>)}</div>{!visibleRows.length&&<div className="empty" style={{marginTop:12}}>적용 중인 기준자료가 없거나 검색 조건에 맞는 자료가 없습니다.</div>}</section>;
}

function ReferenceStatusCards({data}:{data:any}) { const labels:any={university_regional:'대학별 핵심·권장과목',university_track:'계열별 대표 모집단위',school_course:'학교 실제 선택 가능 과목 안내',school_book:'우리 학교 교육과정 / 수강신청 안내',education_official:'교육청 공식 과목 안내'}; const active=(data.referenceUploads||[]).filter((item:any)=>item.active); return <div className="reference-status-grid">{['school_book','university_regional','university_track','school_course','education_official'].map((type)=>(()=>{const item=active.find((row:any)=>row.reference_type===type);return <div className="reference-status-card" key={type}><strong>{item?`${item.criteria_year}학년도 ${labels[type]}`:labels[type]}</strong>{item?<><span>등록 데이터: {Number(item.row_count).toLocaleString()}건</span><span>최근 업로드: {item.created_at}</span><Badge tone="green">적용 중</Badge></>:<span className="panel-sub">아직 등록된 자료가 없습니다.</span>}</div>})())}</div>; }
function ReferencePreviewRows({ rows, type }: { rows: any[]; type: string }) { if (!rows?.length) return null; return <div className="description-list" style={{ marginTop: 12 }}><strong>정규화된 미리보기 (최대 10건)</strong>{rows.slice(0, 10).map((item:any,index:number)=><div className="file-card" key={index}>{type==='university_regional'?<><strong>{item.university || '대학명 미지정'} · {item.department || '모집단위 미지정'}</strong><p className="panel-sub">계열: {item.track || '-'} · 지역: {item.region || '-'}<br/>핵심과목: {item.coreCourses || '-'}<br/>권장과목: {item.recommendedCourses || '-'}<br/>비고: {item.note || '-'}</p></>:type==='university_track'?<><strong>{item.department || '모집단위 미지정'} · {item.courseName || '과목 미지정'}</strong><p className="panel-sub">계열: {item.track || '-'}<br/>과목 영역: {item.subjectArea || '영역 미지정'}<br/>반영 대학: {item.universities?.join(', ') || '-'}</p></>:<p className="panel-sub">{item.courseName || '과목명 미지정'}</p>}</div>)}</div>; }
function TrackAnalysisSummary({ analysis }: { analysis:any }) { const summary=analysis?.summary; if (!summary) return null; return <><div className="message warn" style={{marginTop:14}}><strong>계열별 매트릭스 분석 결과</strong><br/>모집단위 행 {summary.validCount}건 · 인식된 과목 열 {summary.matrixCourseColumnCount}건 · 반영 대학이 있는 과목 셀 {summary.matrixCourseCount}건 · 생성될 과목-대학 관계 {summary.relationshipCount}건<br/>자동 제외 행 {summary.autoExcludedCount||0}건 · 실제 오류 행 {summary.errorCount}건</div>{analysis.autoExcludedRows?.length?<div className="message" style={{marginTop:10}}>자동 제외 행: {analysis.autoExcludedRows.map((row:any)=>`${row.rowNumber}행(${row.reason})`).join(', ')}</div>:null}{analysis.invalidRows?.length?<div className="message error" style={{marginTop:10}}>확인이 필요한 행: {analysis.invalidRows.map((row:any)=>`${row.rowNumber}행(${row.reason})`).join(', ')}</div>:null}</>; }
class ReferenceUploadErrorBoundary extends Component<{children:React.ReactNode},{failed:boolean}> { state={failed:false}; static getDerivedStateFromError(){return {failed:true};} componentDidCatch(error:Error){console.error('기준자료 파일 분석 화면 오류',error);} render(){return this.state.failed?<section className="surface panel"><div className="message error">파일을 분석하는 중 오류가 발생했습니다.<br/>파일 구조를 확인하거나 다시 시도해주세요.</div></section>:this.props.children;} }

function EducationOfficePdfImport({year,session,reload,onNotice}:{year:number;session:Session;reload:()=>Promise<void>;onNotice:(notice:Notice)=>void}){
  const [file,setFile]=useState<File|null>(null); const [rows,setRows]=useState<any[]>([]); const [progress,setProgress]=useState(''); const [busy,setBusy]=useState(false); const [analysis,setAnalysis]=useState<any>(null);
  const analyze=async(next:File|null)=>{setFile(next);setRows([]);setAnalysis(null);if(!next)return;if(!/\.pdf$/i.test(next.name)||next.type&&next.type!=='application/pdf'){onNotice({type:'error',text:'교육청 공식 과목 안내는 PDF 파일만 분석할 수 있습니다.'});return;}setBusy(true);try{pdfjsLib.GlobalWorkerOptions.workerSrc=new URL('pdfjs-dist/legacy/build/pdf.worker.mjs',import.meta.url).toString();const document=await pdfjsLib.getDocument({data:new Uint8Array(await next.arrayBuffer())}).promise;const parsed:any[]=[];let excluded=0;for(let index=0;index<document.numPages;index+=1){setProgress(`PDF 분석 중... ${index+1} / ${document.numPages} 페이지`);const page=await document.getPage(index+1);const content=await page.getTextContent();let lastY:number|undefined;const text=(content.items as any[]).map(item=>{const y=Math.round(Number(item.transform?.[5]||0));const prefix=lastY!==undefined&&Math.abs(y-lastY)>2?'\n':' ';lastY=y;return `${prefix}${item.str||''}`;}).join('');const record=parseEducationGuidePage(text,index+1);if(record)parsed.push({...record,pageCount:document.numPages,excludedPages:0});else excluded+=1;if(index%8===7)await new Promise(resolve=>setTimeout(resolve,0));}const result=await api('/api/education-guide',session.token,{method:'POST',body:JSON.stringify({action:'preview',criteriaYear:year,fileName:next.name,rows:parsed.map(row=>({...row,pageCount:document.numPages,excludedPages:excluded}))})});setRows(parsed);setAnalysis(result);setProgress(`분석 완료: ${document.numPages}쪽 중 과목 설명 ${parsed.length}개를 찾았습니다. 아직 저장되지 않았습니다.`);}catch(error){console.error('교육청 PDF 분석 실패',error);setProgress('');onNotice({type:'error',text:'PDF를 분석하는 중 오류가 발생했습니다. 파일 구조를 확인하거나 다시 시도해주세요.'});}finally{setBusy(false);}};
  const save=async()=>{if(!analysis||!file)return;const existing=analysis.existing||[];if(existing.length&&!window.confirm(`${year} 기준 교육청 공식 과목 안내가 있습니다. 기존 자료는 이력으로 남기고 교체할까요?`))return;setBusy(true);try{const result=await api('/api/education-guide',session.token,{method:'POST',body:JSON.stringify({action:'commit',criteriaYear:year,fileName:file.name,rows:rows.map(row=>({...row,pageCount:analysis.summary.pageCount,excludedPages:analysis.summary.excludedPages})),replaceUploadIds:existing.map((item:any)=>item.id)})});onNotice({type:'success',text:`교육청 공식 과목 안내를 저장했습니다. ${result.savedCount}개 과목을 반영했습니다.`});setFile(null);setRows([]);setAnalysis(null);await reload();}catch(error){onNotice({type:'error',text:error instanceof Error?error.message:'저장하지 못했습니다.'});}finally{setBusy(false);}};
  return <section className="surface panel"><div className="panel-head"><div><h2>교육청 공식 과목 안내</h2><p className="panel-sub">부산광역시교육청 「어떤 과목을 언제 배울까?」 PDF를 과목 설명 참고자료로 저장합니다. 학교 실제 선택 가능 과목은 추가하지 않습니다.</p></div><Badge tone="purple">PDF</Badge></div><div className="toolbar"><label className="secondary-btn"><span>PDF 파일 선택</span><input hidden type="file" accept="application/pdf,.pdf" onChange={e=>analyze(e.target.files?.[0]||null)}/></label>{analysis&&<button className="primary-btn" disabled={busy||!analysis.summary.courseCount} onClick={save}>최종 저장</button>}</div>{progress&&<div className="message warn" style={{marginTop:12}}>{progress}</div>}{analysis&&<><div className="message success" style={{marginTop:12}}>전체 페이지 {analysis.summary.pageCount}쪽 · 인식 과목 {analysis.summary.courseCount}개 · 정상 추출 {analysis.summary.confirmed}개 · 확인 필요 {analysis.summary.needsConfirmation}개 · 제외 페이지 {analysis.summary.excludedPages}쪽</div><div className="description-list" style={{marginTop:12}}>{analysis.summary.sample.map((row:any,index:number)=><div className="file-card" key={index}><strong>{row.courseName}</strong><p className="panel-sub">{row.subjectGroup||'교과 확인 필요'} / {selectionLabel(row.selectionType)} · {row.credits||'학점 확인 필요'} · {row.csatRelation||'수능 관련 확인 필요'}<br/>관련 과목 및 위계: {row.hierarchy||'확인 필요'}<br/>원본 PDF {row.sourcePage}쪽</p></div>)}</div></>}</section>;
}

function AcademicTrackGuideManager({year,data,session,reload,onNotice}:{year:number;data:any;session:Session;reload:()=>Promise<void>;onNotice:(notice:Notice)=>void}){
  const [guide,setGuide]=useState<any>({academicTrack:'humanities',courseName:'',priority:'required',targetGrade:'',targetSemester:'',note:''});
  const save=async()=>{try{await api('/api/action',session.token,{method:'POST',body:JSON.stringify({action:'saveAcademicTrackGuide',guide:{...guide,entranceYear:year}})});setGuide({...guide,courseName:'',note:''});onNotice({type:'success',text:'계열별 과목 선택 기준을 저장했습니다.'});await reload();}catch(error){onNotice({type:'error',text:error instanceof Error?error.message:'저장하지 못했습니다.'});}};
  const deactivate=async(id:string)=>{if(!window.confirm('이 기준을 학생 화면에서 숨길까요? 기존 이력은 삭제하지 않습니다.'))return;try{await api('/api/action',session.token,{method:'POST',body:JSON.stringify({action:'deactivateAcademicTrackGuide',guideId:id})});onNotice({type:'success',text:'계열별 과목 선택 기준을 적용 해제했습니다.'});await reload();}catch(error){onNotice({type:'error',text:error instanceof Error?error.message:'처리하지 못했습니다.'});}};
  const rows=data.trackCourseGuides||[]; const names=[...new Set((data.curriculum||[]).map((row:any)=>row.course_name))];
  return <section className="surface panel"><div className="panel-head"><div><h2>계열별 과목 선택 기준</h2><p className="panel-sub">학교가 정한 필수·우선순위 기준입니다. 교육청 자료나 대학 추천자료에서 자동으로 생성하지 않습니다.</p></div><Badge tone="purple">등록 {rows.length}건</Badge></div><div className="form-grid"><div className="field"><label>계열</label><select className="control" value={guide.academicTrack} onChange={e=>setGuide({...guide,academicTrack:e.target.value})}><option value="humanities">인문계열</option><option value="science">자연계열</option><option value="common">공통(미정 학생)</option></select></div><div className="field"><label>구분</label><select className="control" value={guide.priority} onChange={e=>setGuide({...guide,priority:e.target.value})}><option value="required">필수</option><option value="1">1순위</option><option value="2">2순위</option><option value="3">3순위</option></select></div><div className="field"><label>대상 학년</label><select className="control" value={guide.targetGrade} onChange={e=>setGuide({...guide,targetGrade:e.target.value})}><option value="">전체</option><option value="2">2학년</option><option value="3">3학년</option></select></div><div className="field"><label>대상 학기</label><select className="control" value={guide.targetSemester} onChange={e=>setGuide({...guide,targetSemester:e.target.value})}><option value="">전체</option><option value="1">1학기</option><option value="2">2학기</option></select></div><div className="field full"><label>과목명</label><input className="control" list="curriculum-course-names" value={guide.courseName} onChange={e=>setGuide({...guide,courseName:e.target.value})} placeholder="학교 실제 선택 가능 과목에서 입력"/><datalist id="curriculum-course-names">{names.map((name:any)=><option key={name} value={name}/>)}</datalist></div><div className="field full"><label>비고</label><input className="control" value={guide.note} onChange={e=>setGuide({...guide,note:e.target.value})} placeholder="상담 시 참고할 내용 (선택)"/></div></div><button className="primary-btn" disabled={!guide.courseName.trim()} onClick={save}>계열 기준 저장</button><div className="description-list" style={{marginTop:14}}>{rows.map((row:any)=><div className="file-card" key={row.id}><div className="file-title"><span>{trackLabels[row.academic_track]} · {row.course_name}</span><Badge tone={row.priority==='required'?'red':row.priority==='1'?'pink':row.priority==='2'?'purple':'gray'}>{priorityLabels[row.priority]}</Badge></div><p className="panel-sub">{row.target_grade?`${row.target_grade}학년 ${row.target_semester?`${row.target_semester}학기`:''}`:'대상 학기 공통'}{row.note?` · ${row.note}`:''}</p><button className="ghost-btn" onClick={()=>deactivate(row.id)}>적용 해제</button></div>)}{!rows.length&&<div className="empty">아직 등록된 계열별 과목 선택 기준이 없습니다.</div>}</div></section>;
}

function SchoolCourseBookManager({year,session,reload,onNotice}:{year:number;session:Session;reload:()=>Promise<void>;onNotice:(notice:Notice)=>void}){
 const [academicYear,setAcademicYear]=useState(String(new Date().getFullYear()));const [entryYear,setEntryYear]=useState(String(year));const [file,setFile]=useState<File|null>(null);const [rows,setRows]=useState<any[]>([]);const [analysis,setAnalysis]=useState<any>(null);const [busy,setBusy]=useState(false);
 const choose=async(next:File|null)=>{setFile(next);setRows([]);setAnalysis(null);if(!next)return;const extension=next.name.split('.').pop()?.toLowerCase();if(extension==='hwp'){onNotice({type:'warn',text:'기존 HWP는 브라우저에서 표 구조를 안전하게 읽을 수 없습니다. 한글에서 HWPX로 저장한 뒤 다시 선택해주세요.'});return;}if(extension!=='hwpx'){onNotice({type:'error',text:'우리 학교 교육과정 / 수강신청 안내는 HWP 또는 HWPX 파일만 선택할 수 있습니다.'});return;}setBusy(true);try{const result=await parseSchoolBookHwpx(next);setRows(result.rows);setAnalysis({local:result.summary});onNotice({type:'success',text:`문서를 분석했습니다. 표 ${result.summary.tableCount}개에서 과목 ${result.summary.recognizedCount}개를 찾았습니다. 아직 저장되지 않았습니다.`});}catch(error){console.error('학교 수강신청 책자 분석 실패',error);onNotice({type:'error',text:'문서를 분석하는 중 오류가 발생했습니다. 일부 표 구조를 인식하지 못했을 수 있습니다.'});}finally{setBusy(false);}};
 const preview=async()=>{if(!file||!rows.length)return;setBusy(true);try{const result=await api('/api/school-book',session.token,{method:'POST',body:JSON.stringify({action:'preview',academicYear:Number(academicYear),entryYear:Number(entryYear),fileName:file.name,rows})});setAnalysis(result);}catch(error){onNotice({type:'error',text:error instanceof Error?error.message:'미리보기를 만들지 못했습니다.'});}finally{setBusy(false);}};
 const update=(index:number,key:string,value:any)=>setRows(rows.map((row,n)=>n===index?{...row,[key]:value}:row));
 const save=async()=>{if(!analysis||!file)return;const existing=analysis.existing||[];if(existing.length&&!window.confirm(`${academicYear}학년도 학교 수강신청 안내가 이미 있습니다. 기존 책자 자료는 이력으로 보존하고 교체할까요?`))return;setBusy(true);try{const result=await api('/api/school-book',session.token,{method:'POST',body:JSON.stringify({action:'commit',academicYear:Number(academicYear),entryYear:Number(entryYear),fileName:file.name,rows,replaceUploadIds:existing.map((item:any)=>item.id)})});onNotice({type:'success',text:`학교 수강신청 안내를 저장했습니다. 실제 선택 가능 과목 ${result.savedCount}건을 반영했습니다.`});setFile(null);setRows([]);setAnalysis(null);await reload();}catch(error){onNotice({type:'error',text:error instanceof Error?error.message:'저장하지 못했습니다.'});}finally{setBusy(false);}};
 return <section className="surface panel"><div className="panel-head"><div><h2>우리 학교 교육과정 / 수강신청 안내</h2><p className="panel-sub">학교 실제 개설 과목과 선택 규칙을 위한 운영 기준자료입니다. 교육청 공식 과목 안내와는 별도로 관리합니다.</p></div><Badge tone="pink">HWPX</Badge></div><div className="form-grid"><div className="field"><label>기준학년도</label><input className="control" inputMode="numeric" value={academicYear} onChange={e=>setAcademicYear(e.target.value)}/></div><div className="field"><label>대상 입학년도</label><input className="control" inputMode="numeric" value={entryYear} onChange={e=>setEntryYear(e.target.value)}/></div><div className="field full"><label>수강신청 안내 책자</label><input className="control" type="file" accept=".hwp,.hwpx" onChange={e=>choose(e.target.files?.[0]||null)}/></div></div>{analysis?.local&&<div className="message warn" style={{marginTop:12}}>문단 {analysis.local.paragraphCount}개 · 표 {analysis.local.tableCount}개 · 인식 과목 {analysis.local.recognizedCount}개 · 분류 확인 필요 {analysis.local.needsConfirmation}개. 표에 없는 정보는 비워 둡니다.</div>}{rows.length>0&&<><div className="toolbar" style={{marginTop:12}}><button className="secondary-btn" disabled={busy} onClick={preview}>{busy?'분석 중...':'분석 결과 미리보기'}</button>{analysis?.summary&&<button className="primary-btn" disabled={busy||!analysis.summary.validCount} onClick={save}>최종 저장</button>}</div><div className="description-list" style={{marginTop:12}}>{rows.slice(0,20).map((row,index)=><div className="file-card" key={`${row.sourceLocation}-${index}`}><div className="file-title"><input className="control" value={row.subjectName} onChange={e=>update(index,'subjectName',e.target.value)} aria-label="과목명"/><Badge tone="purple">{row.sourceLocation}</Badge></div><div className="form-grid" style={{marginTop:8}}><div className="field"><label>교과</label><input className="control" value={row.subjectGroup} onChange={e=>update(index,'subjectGroup',e.target.value)}/></div><div className="field"><label>교육과정 분류</label><select className="control" value={row.curriculumCategory} onChange={e=>update(index,'curriculumCategory',e.target.value)}><option value="">미지정</option><option value="common">공통</option><option value="general">일반선택</option><option value="career">진로선택</option><option value="convergence">융합선택</option></select></div><div className="field"><label>학교 운영</label><select className="control" value={row.schoolRequirement} onChange={e=>update(index,'schoolRequirement',e.target.value)}><option value="optional">학교 선택</option><option value="required">학교 필수</option></select></div><div className="field"><label>대상</label><div className="split"><input className="control" value={row.targetGrade} onChange={e=>update(index,'targetGrade',e.target.value)} placeholder="학년"/><input className="control" value={row.targetSemester} onChange={e=>update(index,'targetSemester',e.target.value)} placeholder="학기"/></div></div></div><div className="chips" style={{marginTop:8}}><label><input type="checkbox" checked={!!row.csatPriority} onChange={e=>update(index,'csatPriority',e.target.checked)}/> 수능 대비 우선 안내</label><label><input type="checkbox" checked={!!row.humanitiesPriority} onChange={e=>update(index,'humanitiesPriority',e.target.checked)}/> 인문 우선</label><label><input type="checkbox" checked={!!row.sciencePriority} onChange={e=>update(index,'sciencePriority',e.target.checked)}/> 자연 우선</label></div></div>)}</div>{rows.length>20&&<div className="message" style={{marginTop:10}}>미리보기는 처음 20과목만 표시합니다. 전체 {rows.length}건은 최종 저장 대상에 포함됩니다.</div>}{analysis?.summary&&<div className="message success" style={{marginTop:12}}>저장 가능 {analysis.summary.validCount}건 · 오류 {analysis.summary.errorCount}건 · 기존 적용 자료 {analysis.existing?.length||0}개</div>}</>}</section>;
}

function SchoolBookEntryEditor({entries,session,reload,onNotice}:{entries:any[];session:Session;reload:()=>Promise<void>;onNotice:(notice:Notice)=>void}){
 const [drafts,setDrafts]=useState<Record<string,any>>({}); const [chosen,setChosen]=useState<string[]>([]); const [busy,setBusy]=useState(false);
 useEffect(()=>setDrafts(Object.fromEntries(entries.map((entry:any)=>[entry.id,{...entry}]))),[entries]);
 const update=(entryId:string,key:string,value:any)=>setDrafts(current=>({...current,[entryId]:{...current[entryId],[key]:value}}));
 const save=async(entryId:string)=>{const entry=drafts[entryId];if(!entry)return;setBusy(true);try{await api('/api/school-book',session.token,{method:'POST',body:JSON.stringify({action:'updateEntry',entry})});onNotice({type:'success',text:`${entry.subject_name} 과목 기준을 저장했습니다.`});await reload();}catch(error){onNotice({type:'error',text:error instanceof Error?error.message:'과목 기준을 저장하지 못했습니다.'});}finally{setBusy(false);}};
 const bulk=async(field:string,enabled:boolean)=>{if(!chosen.length){onNotice({type:'warn',text:'먼저 일괄 변경할 과목을 선택해주세요.'});return;}if(!window.confirm(`선택한 ${chosen.length}개 과목의 기준을 ${enabled?'지정':'해제'}할까요?`))return;setBusy(true);try{const result=await api('/api/school-book',session.token,{method:'POST',body:JSON.stringify({action:'bulkFlags',entryIds:chosen,field,enabled})});onNotice({type:'success',text:`${result.count}개 과목의 기준을 변경했습니다.`});setChosen([]);await reload();}catch(error){onNotice({type:'error',text:error instanceof Error?error.message:'일괄 변경하지 못했습니다.'});}finally{setBusy(false);}};
 const toggle=(entryId:string)=>setChosen(current=>current.includes(entryId)?current.filter(id=>id!==entryId):[...current,entryId]);
 return <section className="surface panel"><div className="panel-head"><div><h2>저장된 학교 기준 과목</h2><p className="panel-sub">학교 운영 필수, 수능 준비 우선, 계열 우선은 서로 다른 기준입니다. 수능 준비 우선은 교육과정상 필수가 아닌 학교 진학지도 참고 기준입니다.</p></div><Badge tone="purple">적용 {entries.length}과목</Badge></div>{!entries.length?<div className="empty">아직 최종 저장된 학교 수강신청 안내 자료가 없습니다.</div>:<><div className="toolbar"><button className="secondary-btn" disabled={busy} onClick={()=>bulk('csat_priority',true)}>수능 준비 우선 지정</button><button className="ghost-btn" disabled={busy} onClick={()=>bulk('csat_priority',false)}>수능 준비 우선 해제</button><button className="secondary-btn" disabled={busy} onClick={()=>bulk('humanities_priority',true)}>인문 우선 지정</button><button className="secondary-btn" disabled={busy} onClick={()=>bulk('science_priority',true)}>자연 우선 지정</button></div><div className="description-list" style={{marginTop:12}}>{entries.map((source:any)=>{const entry=drafts[source.id]||source;return <div className="file-card" key={source.id}><div className="file-title"><label><input type="checkbox" checked={chosen.includes(source.id)} onChange={()=>toggle(source.id)}/> 일괄 선택</label><input className="control" value={entry.subject_name||''} onChange={e=>update(source.id,'subject_name',e.target.value)} aria-label="과목명"/></div><div className="form-grid" style={{marginTop:8}}><div className="field"><label>교과</label><input className="control" value={entry.subject_group||''} onChange={e=>update(source.id,'subject_group',e.target.value)}/></div><div className="field"><label>교육과정 분류</label><select className="control" value={entry.curriculum_category||''} onChange={e=>update(source.id,'curriculum_category',e.target.value)}><option value="">미지정</option><option value="common">공통</option><option value="general">일반선택</option><option value="career">진로선택</option><option value="convergence">융합선택</option></select></div><div className="field"><label>학교 운영</label><select className="control" value={entry.school_requirement||'optional'} onChange={e=>update(source.id,'school_requirement',e.target.value)}><option value="optional">학교 선택</option><option value="required">학교 필수</option></select></div><div className="field"><label>대상</label><span className="panel-sub">{entry.target_grade?`${entry.target_grade}학년 ${entry.target_semester||'?'}학기`:'책자에서 확인 필요'}</span></div></div><div className="chips" style={{marginTop:8}}><label><input type="checkbox" checked={!!entry.csat_priority} onChange={e=>update(source.id,'csat_priority',e.target.checked)}/> 수능 준비 우선</label><label><input type="checkbox" checked={!!entry.humanities_priority} onChange={e=>update(source.id,'humanities_priority',e.target.checked)}/> 인문 우선</label><label><input type="checkbox" checked={!!entry.science_priority} onChange={e=>update(source.id,'science_priority',e.target.checked)}/> 자연 우선</label><button className="ghost-btn" disabled={busy} onClick={()=>save(source.id)}>이 과목 저장</button></div></div>})}</div></>}</section>;
}

function ReferenceView({year,data,session,reload}:{year:number;data:any;session:Session;reload:()=>Promise<void>}) {
  const [course,setCourse]=useState({entranceYear:year,targetGrade:2,targetSemester:1,area:'국어',courseName:'',selectionType:'general',offered:true,note:''});
  const emptyDescription={entranceYear:year,courseName:'',overview:'',learningContent:'',courseNature:'',relatedCareers:'',recommendedGrade:'',recommendedSemester:'',selectionType:'',note:'',sourceName:'선생님 직접 입력',sourceYear:''};
  const [description,setDescription]=useState<any>(emptyDescription);
  const [notice,setNotice]=useState<Notice>(null);
  const save=async()=>{try{await api('/api/action',session.token,{method:'POST',body:JSON.stringify({action:'saveCurriculum',course:{...course,entranceYear:year}})});setCourse({...course,courseName:'',note:''});setNotice({type:'success',text:'학교 교육과정에 과목을 등록했습니다.'});await reload();}catch(e){setNotice({type:'error',text:e instanceof Error?e.message:'등록하지 못했습니다.'});}};
  const saveDescription=async()=>{try{await api('/api/action',session.token,{method:'POST',body:JSON.stringify({action:'saveCourseDescription',description:{...description,entranceYear:year}})});setNotice({type:'success',text:'과목 설명을 저장했습니다. 학생 화면에는 선택된 설명이 표시됩니다.'});setDescription(emptyDescription);await reload();}catch(e){setNotice({type:'error',text:e instanceof Error?e.message:'저장하지 못했습니다.'});}};
  const editDescription=(item:any)=>setDescription({entranceYear:year,courseName:item.course_name,overview:item.overview||'',learningContent:item.learning_content||'',courseNature:item.course_nature||'',relatedCareers:item.related_careers||'',recommendedGrade:item.recommended_grade||'',recommendedSemester:item.recommended_semester||'',selectionType:item.selection_type||'',note:item.note||'',sourceName:item.source_name||'선생님 직접 입력',sourceYear:item.source_year||''});
  return <>
    <ReferenceStatusCards data={data}/><SchoolCourseBookManager year={year} session={session} reload={reload} onNotice={setNotice}/><SchoolBookEntryEditor entries={data.schoolBookEntries||[]} session={session} reload={reload} onNotice={setNotice}/><EducationOfficePdfImport year={year} session={session} reload={reload} onNotice={setNotice}/><AcademicTrackGuideManager year={year} data={data} session={session} reload={reload} onNotice={setNotice}/><ReferenceUploadErrorBoundary><ReferenceUploadManagerV2 data={data} session={session} reload={reload} onNotice={setNotice}/></ReferenceUploadErrorBoundary>
    <section className="surface panel"><div className="panel-head"><div><h2>학교 교육과정</h2><p className="panel-sub">입학년도별로 과목을 관리합니다. 기존 과목 목록은 기본 자료로 유지됩니다.</p></div><Badge tone="purple">등록 {data.curriculum.length}과목</Badge></div><div className="form-grid"><div className="field"><label>대상 학년</label><select className="control" value={course.targetGrade} onChange={e=>setCourse({...course,targetGrade:Number(e.target.value)})}><option value="2">2학년</option><option value="3">3학년</option></select></div><div className="field"><label>대상 학기</label><select className="control" value={course.targetSemester} onChange={e=>setCourse({...course,targetSemester:Number(e.target.value)})}><option value="1">1학기</option><option value="2">2학기</option></select></div><div className="field"><label>교과 영역</label><input className="control" value={course.area} onChange={e=>setCourse({...course,area:e.target.value})}/></div><div className="field"><label>선택 분류</label><select className="control" value={course.selectionType} onChange={e=>setCourse({...course,selectionType:e.target.value})}><option value="general">일반선택</option><option value="career">진로선택</option><option value="convergence">융합선택</option></select></div><div className="field full"><label>과목명</label><input className="control" value={course.courseName} onChange={e=>setCourse({...course,courseName:e.target.value})}/></div></div><NoticeBox notice={notice}/><button className="primary-btn" disabled={!course.courseName.trim()} onClick={save}>과목 등록</button></section>
    <section className="surface panel"><div className="panel-head"><div><h2>과목 설명</h2><p className="panel-sub">선생님이 직접 작성한 설명입니다. 공식 자료가 등록되면 기존 설명은 보존한 채 비교·선택할 수 있습니다.</p></div><Badge tone="pink">{data.courseDescriptions?.length || 0}개</Badge></div><div className="form-grid"><div className="field full"><label>과목명</label><input className="control" value={description.courseName} onChange={e=>setDescription({...description,courseName:e.target.value})} placeholder="예: 생명과학Ⅰ"/></div><div className="field full"><label>과목 개요</label><textarea className="control" value={description.overview} onChange={e=>setDescription({...description,overview:e.target.value})}/></div><div className="field full"><label>주요 학습 내용</label><textarea className="control" value={description.learningContent} onChange={e=>setDescription({...description,learningContent:e.target.value})}/></div><div className="field"><label>과목 성격</label><input className="control" value={description.courseNature} onChange={e=>setDescription({...description,courseNature:e.target.value})}/></div><div className="field"><label>관련 진로·학과</label><input className="control" value={description.relatedCareers} onChange={e=>setDescription({...description,relatedCareers:e.target.value})}/></div><div className="field"><label>권장 학년</label><select className="control" value={description.recommendedGrade} onChange={e=>setDescription({...description,recommendedGrade:e.target.value})}><option value="">미지정</option><option value="2">2학년</option><option value="3">3학년</option></select></div><div className="field"><label>권장 학기</label><select className="control" value={description.recommendedSemester} onChange={e=>setDescription({...description,recommendedSemester:e.target.value})}><option value="">미지정</option><option value="1">1학기</option><option value="2">2학기</option></select></div><div className="field"><label>선택과목 유형</label><select className="control" value={description.selectionType} onChange={e=>setDescription({...description,selectionType:e.target.value})}><option value="">미지정</option><option value="general">일반선택</option><option value="career">진로선택</option><option value="convergence">융합선택</option></select></div><div className="field"><label>출처/기준연도</label><div className="split"><input className="control" value={description.sourceName} onChange={e=>setDescription({...description,sourceName:e.target.value})} placeholder="선생님 직접 입력"/><input className="control" inputMode="numeric" value={description.sourceYear} onChange={e=>setDescription({...description,sourceYear:e.target.value})} placeholder="예: 2028"/></div></div><div className="field full"><label>비고</label><textarea className="control" value={description.note} onChange={e=>setDescription({...description,note:e.target.value})}/></div></div><button className="primary-btn" disabled={!description.courseName.trim()} onClick={saveDescription}>과목 설명 저장</button>{data.courseDescriptions?.length ? <div className="description-list">{data.courseDescriptions.map((item:any)=><div className="file-card" key={item.id}><div className="file-title"><span>{item.course_name}</span><Badge tone={item.source_kind==='official'?'green':item.source_kind==='merged'?'purple':'pink'}>{item.source_kind==='official'?'공식 자료':item.source_kind==='merged'?'병합 설명':'직접 입력'}</Badge></div><p className="panel-sub">{item.overview || '과목 개요를 아직 입력하지 않았습니다.'}</p><button className="ghost-btn" style={{marginTop:10}} onClick={()=>editDescription(item)}>수정</button></div>)}</div> : <div className="empty" style={{marginTop:14}}>등록된 과목 설명이 없습니다.</div>}</section>
    <section className="surface panel"><h2>공식 과목 안내 자료 가져오기 준비</h2><p className="panel-sub">향후 교육부·교육 관련 기관의 자료 파일을 올리면 과목명 완전 일치 여부를 먼저 확인합니다. 이름이 다르면 자동으로 합치지 않고 ‘매칭 확인 필요’로 남깁니다.</p><div className="message warn">기존 직접 입력 설명은 자동으로 바뀌지 않습니다. 자료별로 기존 설명 유지, 공식 자료로 교체, 병합 중 하나를 선택한 뒤 학생 화면에 표시할 설명을 정합니다.</div></section>
    <section className="surface panel"><h2>대학별 핵심·권장과목 자료</h2><p className="panel-sub">대학별 자료와 계열별 자료는 서로 다른 구조로 보존하도록 데이터 영역을 준비했습니다. 실제 2028학년도 자료 파일을 받으면 가져오기 기능을 연결할 수 있습니다.</p><div className="message warn">현재 저장소에는 대학 기준자료 원본이 없어 자동 등록은 아직 수행하지 않았습니다.</div></section>
  </>;
}

function SettingsView({year,data,session,reload,onLogout}:{year:number;data:any;session:Session;reload:()=>Promise<void>;onLogout:()=>void}) {
  const [notice,setNotice]=useState<Notice>(null);
  const [passwords,setPasswords]=useState({currentPassword:'',newPassword:'',confirmPassword:''});
  const [restorePreview,setRestorePreview]=useState<any>(null);
  const [restoreFile,setRestoreFile]=useState<File|null>(null);
  const setRound=async(roundNumber:number,status:string)=>{try{await api('/api/action',session.token,{method:'POST',body:JSON.stringify({action:'setRound',entranceYear:year,roundNumber,status,title:`${roundNumber}차 신청안 작성`})});await reload();}catch(e){setNotice({type:'error',text:e instanceof Error?e.message:'신청 기간을 변경하지 못했습니다.'});}};
  const changePassword=async()=>{if(passwords.newPassword!==passwords.confirmPassword){setNotice({type:'error',text:'새 비밀번호와 확인값이 다릅니다.'});return;}if(!passwords.newPassword){setNotice({type:'error',text:'새 비밀번호를 입력해주세요.'});return;}try{await api('/api/action',session.token,{method:'POST',body:JSON.stringify({action:'changeTeacherPassword',currentPassword:passwords.currentPassword,newPassword:passwords.newPassword})});setPasswords({currentPassword:'',newPassword:'',confirmPassword:''});window.alert('비밀번호를 변경했습니다. 보안을 위해 다시 로그인해주세요.');onLogout();}catch(e){setNotice({type:'error',text:e instanceof Error?e.message:'비밀번호를 변경하지 못했습니다.'});}};
  const downloadBackup=async()=>{try{const response=await fetch('/api/backup',{headers:{Authorization:`Bearer ${session.token}`}});if(!response.ok)throw new Error('백업 파일을 만들지 못했습니다.');const blob=await response.blob();const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`course-planner-backup-${new Date().toISOString().slice(0,16).replace(/[-:T]/g,'')}.json`;anchor.click();URL.revokeObjectURL(url);setNotice({type:'success',text:'백업이 완료되었습니다.'});}catch(e){setNotice({type:'error',text:e instanceof Error?e.message:'백업에 실패했습니다.'});}};
  const previewRestore=async(file:File|null)=>{setRestoreFile(file);setRestorePreview(null);if(!file)return;try{const body=await file.text();const result=await api('/api/backup',session.token,{method:'POST',body});setRestorePreview(result);}catch(e){setNotice({type:'error',text:e instanceof Error?e.message:'백업 파일을 분석하지 못했습니다.'});}};
  const commitRestore=async()=>{if(!restoreFile||!restorePreview?.preview)return;if(!window.confirm('복구 작업은 현재 데이터를 변경할 수 있습니다. 전체 백업 데이터를 교체 복구하시겠습니까?'))return;try{const body=await restoreFile.text();const result=await api('/api/backup',session.token,{method:'POST',headers:{'x-backup-action':'commit'},body});setNotice({type:'success',text:`복구가 완료되었습니다. 총 ${result.restored ? Object.values(result.restored).reduce((a:number,b:any)=>a+Number(b||0),0) : 0}건을 반영했습니다.`});setRestoreFile(null);setRestorePreview(null);await reload();}catch(e){setNotice({type:'error',text:e instanceof Error?e.message:'복구에 실패했습니다.'});}};
  return <><section className="surface panel"><div className="panel-head"><div><h2>차수별 신청 기간</h2><p className="panel-sub">차수는 숫자로 관리되어 3차 이후에도 추가할 수 있습니다.</p></div></div>{[1,2,3].map(n=>{const round=data.rounds.find((r:any)=>r.round_number===n);const open=round?.status==='open';return <div className="file-card" key={n}><div className="file-title"><span>{n}차 신청안 작성</span><Badge tone={open?'green':'gray'}>{open?'진행 중':'마감'}</Badge></div><button className={open?'danger-btn':'primary-btn'} style={{marginTop:10}} onClick={()=>setRound(n,open?'closed':'open')}>{open?'신청 기간 마감':'신청 기간 열기'}</button></div>;})}</section><section className="surface panel"><div className="panel-head"><div><h2>데이터 관리</h2><p className="panel-sub">학생 신청안, 공식 결과, 기준자료와 확인 이력을 JSON으로 보관합니다. 인증 비밀값은 포함하지 않습니다.</p></div></div><div className="toolbar"><button className="secondary-btn" onClick={downloadBackup}>전체 백업</button><label className="secondary-btn"><span>백업에서 복구</span><input type="file" accept="application/json,.json" hidden onChange={e=>previewRestore(e.target.files?.[0]||null)}/></label></div>{restorePreview&&<div className="message warn" style={{marginTop:12}}>{restorePreview.warning}<br/>복구 예정 총 {restorePreview.total}건 <button className="danger-btn" style={{marginTop:10}} onClick={commitRestore}>최종 복구</button></div>}<NoticeBox notice={notice}/></section><section className="surface panel"><div className="panel-head"><div><h2>선생님 로그인 비밀번호 변경</h2><p className="panel-sub">변경하면 현재 로그인된 선생님 화면은 모두 다시 로그인해야 합니다. 비밀번호 값은 저장 후 화면에 표시되지 않습니다.</p></div></div><div className="form-grid"><div className="field"><label>현재 비밀번호</label><input className="control" type="password" autoComplete="current-password" value={passwords.currentPassword} onChange={e=>setPasswords({...passwords,currentPassword:e.target.value})}/></div><div className="field"><label>새 비밀번호</label><input className="control" type="password" autoComplete="new-password" value={passwords.newPassword} onChange={e=>setPasswords({...passwords,newPassword:e.target.value})}/></div><div className="field"><label>새 비밀번호 확인</label><input className="control" type="password" autoComplete="new-password" value={passwords.confirmPassword} onChange={e=>setPasswords({...passwords,confirmPassword:e.target.value})}/></div></div><NoticeBox notice={notice}/><button className="primary-btn" onClick={changePassword}>비밀번호 변경</button></section></>;
}
